insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-001','module-01','À quoi sert JavaScript ?','exercise',1,'Une page web peut utiliser plusieurs langages. HTML décrit ce qui existe, par exemple un titre ou un bouton. CSS règle leur apparence, comme la couleur ou l’espacement. JavaScript ajoute des actions et des calculs.

console.log(...) affiche le résultat entre ses parenthèses. Le navigateur calcule ici 4 * 3, puis montre 12. JavaScript peut aussi réagir à un clic ou afficher une réponse; HTML et CSS ont les deux autres rôles décrits plus haut.','console.log(4 * 3);','Relie chaque besoin au rôle qui le prend en charge.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
