insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-002','module-01','Choisir un type de donnée','exercise',2,'JavaScript distingue les nombres, les textes et les booléens. Un number sert aux calculs. Une string est une suite de caractères écrite entre guillemets. Un boolean vaut seulement true ou false et exprime un oui ou un non.

Les guillemets changent le type : 42 sans guillemets est un nombre, tandis que "42" est du texte. Deux valeurs qui se ressemblent à l’écran ne sont donc pas forcément utilisables de la même façon.','console.log(3);
console.log("Maya");
console.log(false);','Classe chaque valeur dans son type JavaScript.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
