do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-002' and version=2 and public_content<>'{"id":"mvp-002","version":2,"title":"Choisir un type de donnée","theory":[{"type":"heading","level":2,"text":"La forme d’une valeur compte"},{"type":"paragraph","segments":[{"type":"text","text":"JavaScript distingue les nombres, les textes et les booléens. Un "},{"type":"strong","text":"number"},{"type":"text","text":" sert aux calculs. Une "},{"type":"strong","text":"string"},{"type":"text","text":" est une suite de caractères écrite entre guillemets. Un "},{"type":"strong","text":"boolean"},{"type":"text","text":" vaut seulement "},{"type":"code","text":"true"},{"type":"text","text":" ou "},{"type":"code","text":"false"},{"type":"text","text":" et exprime un oui ou un non."}]},{"type":"code","language":"javascript","code":"console.log(3);\nconsole.log(\"Maya\");\nconsole.log(false);","output":"3 puis Maya puis false"},{"type":"paragraph","segments":[{"type":"text","text":"Les guillemets changent le type : "},{"type":"code","text":"42"},{"type":"text","text":" sans guillemets est un nombre, tandis que "},{"type":"code","text":"\"42\""},{"type":"text","text":" est du texte. Deux valeurs qui se ressemblent à l’écran ne sont donc pas forcément utilisables de la même façon."}]}],"interactions":[{"id":"types","prompt":"Classe chaque valeur dans son type JavaScript.","definition":{"kind":"classify","items":[{"id":"score","label":"18"},{"id":"code","label":"\"18\""},{"id":"actif","label":"true"},{"id":"pseudo","label":"\"Noé\""}],"categories":[{"id":"number","label":"number : nombre"},{"id":"string","label":"string : texte"},{"id":"boolean","label":"boolean : vrai ou faux"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-002 version 2'; end if; end $$;
