insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-003','module-01','Déclarer une variable','exercise',3,'Une variable associe un nom à une valeur pour qu’on puisse la réutiliser. let et const déclarent ce nom. Utilise let si le programme doit lui attribuer une autre valeur plus tard; utilise const si aucune nouvelle affectation n’est prévue.

Le signe = attribue la valeur de droite au nom de gauche. Dans cet exemple, niveau change; pseudo garde son texte. Le bon choix dépend de ce que le programme fera ensuite, pas du nom choisi.','let niveau = 1;
niveau = 2;
const pseudo = "Sam";','Pour chaque ligne à compléter, choisis le mot qui correspond à la suite annoncée.',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
