insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-004','module-01','Comprendre let et const','exercise',4,'Dans un jeu, tu dois garder le prénom du joueur et son score. Une variable permet de retrouver une valeur grâce à un nom. Ici, prenom est le nom ; Lina est la valeur.

Le prénom restera le même pendant cette partie. On choisit const pour empêcher de lui attribuer une autre valeur par erreur. Le mot const est suivi du nom, puis de = et de la valeur.

Le signe = signifie ici « attribuer la valeur située à droite au nom situé à gauche ». On appelle cette action une affectation. Ce signe ne pose pas une question d’égalité comme en mathématiques.

Le score doit évoluer quand le joueur gagne des points. On utilise let parce que ce nom recevra une nouvelle valeur.','const prenom = "Lina";
console.log(prenom);','Classe chaque nom selon ce qui se passe dans l’exemple.
Le score commence à 2. On lui ajoute ensuite 3. Indique sa valeur après chaque ligne.
Tu enregistres le prénom Lina et tu veux empêcher sa réaffectation. Quel mot protège ce prénom contre une nouvelle affectation ?',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
