insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-005','module-01','Lire console.log','exercise',5,'console.log(...) affiche ce qui se trouve entre ses parenthèses. Il est utile pour vérifier un calcul ou voir une valeur pendant l’apprentissage. Un nombre entre guillemets reste du texte; sans guillemets, l’opérateur + peut additionner.

Dans le premier appel, JavaScript additionne deux nombres. Dans le second, il réunit deux textes. Chaque appel affiche son propre résultat, dans le même ordre que les lignes.','console.log(2 + 5);
console.log("2" + "5");','Associe chaque appel à ce qu’il affiche.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
