do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-005' and version=2 and public_content<>'{"id":"mvp-005","version":2,"title":"Lire console.log","theory":[{"type":"heading","level":2,"text":"Afficher une valeur pour la lire"},{"type":"paragraph","segments":[{"type":"code","text":"console.log(...)"},{"type":"text","text":" affiche ce qui se trouve entre ses parenthèses. Il est utile pour vérifier un calcul ou voir une valeur pendant l’apprentissage. Un nombre entre guillemets reste du texte; sans guillemets, l’opérateur "},{"type":"code","text":"+"},{"type":"text","text":" peut additionner."}]},{"type":"code","language":"javascript","code":"console.log(2 + 5);\nconsole.log(\"2\" + \"5\");","output":"7 puis 25"},{"type":"paragraph","segments":[{"type":"text","text":"Dans le premier appel, JavaScript additionne deux nombres. Dans le second, il réunit deux textes. Chaque appel affiche son propre résultat, dans le même ordre que les lignes."}]}],"interactions":[{"id":"sorties","prompt":"Associe chaque appel à ce qu’il affiche.","definition":{"kind":"matching","left":[{"id":"sum","label":"console.log(2 + 5)"},{"id":"join","label":"console.log(\"2\" + \"5\")"}],"right":[{"id":"seven","label":"7"},{"id":"twentyfive","label":"25"}],"oneToOne":true}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-005 version 2'; end if; end $$;
