insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-006','module-01','Suivre les affectations','exercise',6,'Une variable garde sa valeur jusqu’à la prochaine affectation. score += 2 signifie qu’on prend le score actuel, qu’on ajoute 2, puis qu’on range le nouveau résultat dans score. L’ordre des instructions détermine donc le résultat.

Pour suivre le programme, note la valeur après chaque ligne qui change le nom. La dernière ligne remplace 6 par 5; elle ne retire pas 1 à la valeur de départ.','let score = 4;
score += 2;
score = score - 1;','Écris la valeur de score après chaque ligne. Réponds avec des nombres, dans les cases indiquées.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
