insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-007','module-01','Respecter les majuscules','exercise',7,'JavaScript est sensible à la casse : une majuscule et une minuscule ne sont pas interchangeables dans un nom. score, Score et SCORE désignent trois identifiants différents. Il faut réutiliser exactement l’écriture choisie à la déclaration.

Si l’appel affichait Score avec une majuscule, il ne retrouverait pas le nom score déclaré ici. Avant de lire une ligne, compare toutes les lettres, pas seulement le sens du mot.','const score = 8;
console.log(score);','Un programme déclare `const score = 8`. Quel identifiant reprend exactement le même nom ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
