insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-008','module-01','Ton premier profil de joueur','project',8,'Un profil peut être affiché à partir de valeurs simples. On garde le prénom dans une chaîne et le score dans un nombre. + additionne deux nombres; console.log affiche la valeur placée entre ses parenthèses.

Le projet suit un seul profil : on vérifie le bonus, le prénom affiché et le score final. Les étapes se rapportent aux mêmes deux valeurs.','const prenom = "Lina";
let score = 6;
score += 2;
console.log(prenom);
console.log(score);','Le score commence à 6 et reçoit 2 points. Quelle expression complète son affectation ?
Associe chaque donnée à l’appel console.log qui l’affiche.
Place les deux appels console.log dans l’ordre où le code les exécute.
Quel score est affiché après le bonus ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
