do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-008' and version=2 and public_content<>'{"id":"mvp-008","version":2,"title":"Ton premier profil de joueur","theory":[{"type":"heading","level":2,"text":"Un prénom et un score"},{"type":"paragraph","segments":[{"type":"text","text":"Un profil peut être affiché à partir de valeurs simples. On garde le prénom dans une chaîne et le score dans un nombre. "},{"type":"code","text":"+"},{"type":"text","text":" additionne deux nombres; "},{"type":"code","text":"console.log"},{"type":"text","text":" affiche la valeur placée entre ses parenthèses."}]},{"type":"code","language":"javascript","code":"const prenom = \"Lina\";\nlet score = 6;\nscore += 2;\nconsole.log(prenom);\nconsole.log(score);","output":"Lina puis 8"},{"type":"paragraph","segments":[{"type":"text","text":"Le projet suit un seul profil : on vérifie le bonus, le prénom affiché et le score final. Les étapes se rapportent aux mêmes deux valeurs."}]}],"interactions":[{"id":"bonus","prompt":"Le score commence à 6 et reçoit 2 points. Quelle expression complète son affectation ?","definition":{"kind":"blanks","blanks":[{"id":"expression","label":"score = score + ___","mode":"options","options":[{"id":"two","label":"2"},{"id":"six","label":"6"},{"id":"eight","label":"8"}]}]}},{"id":"message","prompt":"Associe chaque donnée à l’appel console.log qui l’affiche.","definition":{"kind":"matching","left":[{"id":"lina","label":"Lina"},{"id":"huit","label":"8"}],"right":[{"id":"prenom","label":"console.log(prenom)"},{"id":"total","label":"console.log(score)"}],"oneToOne":true}},{"id":"affichage","prompt":"Place les deux appels console.log dans l’ordre où le code les exécute.","definition":{"kind":"ordering","items":[{"id":"score","label":"Afficher le score final"},{"id":"prenom","label":"Afficher le prénom"}]}},{"id":"sortie","prompt":"Quel score est affiché après le bonus ?","definition":{"kind":"choice","mode":"single","options":[{"id":"six","label":"6"},{"id":"eight","label":"8"},{"id":"sixtytwo","label":"62"}]}}],"project":{"steps":["bonus","message","affichage","sortie"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-008 version 2'; end if; end $$;
