insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-009','module-02','Compter les caractères','exercise',9,'Une chaîne est un texte. Sa propriété length donne le nombre de caractères qu’elle contient; les guillemets qui délimitent le texte ne font pas partie de la chaîne.

Les lettres et les espaces comptent chacun pour un caractère. Pour salut toi, la longueur est 9 : cinq lettres, un espace et trois lettres.','const mot = "chat";
console.log(mot.length);','Associe chaque texte à sa longueur. Ne compte pas les guillemets.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
