insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-010','module-02','Lire un caractère par son index','exercise',10,'Un index désigne une position et commence à zéro. Ainsi, le premier caractère est à l’index 0, le deuxième à l’index 1. Les espaces occupent aussi une position.

On peut écrire les positions sous le texte : l vaut 0, u vaut 1, n vaut 2 et e vaut 3. Lire un index ne modifie pas la chaîne.','const mot = "lune";
console.log(mot[2]);','Quel caractère est lu par mot[1] ? Réponds par le caractère seul.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
