insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-011','module-02','Réunir deux textes','exercise',11,'Entre deux chaînes, l’opérateur + les concatène : il place leurs caractères l’un après l’autre. Il n’ajoute ni espace ni ponctuation de lui-même.

L’espace après Salut est inclus dans la première chaîne. Si on l’enlève, le résultat devient SalutNoé!; chaque espace souhaité doit être écrit explicitement.','const prenom = "Noé";
console.log("Salut " + prenom + "!");','Quel signe réunit les deux parties du message sans ajouter de caractère ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
