insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-012','module-02','Convertir entre nombre et texte','exercise',12,'String(valeur) transforme une valeur en texte; Number(texte) transforme un texte numérique en nombre. Le type détermine l’opération : "18" + 1 concatène du texte, tandis que Number("18") + 1 calcule.

Garde les guillemets quand la valeur est du texte : "18" est différent du nombre 18. Convertis vers le type dont l’opération a besoin.','const ageTexte = "18";
const age = Number(ageTexte);
console.log(age + 1);
const message = String(age) + " ans";
console.log(message);','Tu reçois le texte `"18"` et veux calculer un âge augmenté de 1. Quelle conversion faut-il faire d’abord ?
Quel appel transforme le nombre 18 en texte pour le coller à `" ans"` ?',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
