insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-013','module-02','Respecter la priorité des opérations','exercise',13,'JavaScript suit les priorités mathématiques : les parenthèses d’abord, puis multiplication et division, puis addition et soustraction. À priorité égale, il avance de gauche à droite.

Le produit 2 * 4 vaut 8 avant l’addition. Avec (3 + 2) * 4, les parenthèses changent l’ordre et le résultat devient 20.','const total = 3 + 2 * 4;
console.log(total);','Suis les priorités et indique le résultat de chaque étape puis le total.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
