insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-014','module-02','Réparer le calcul d’une moyenne','exercise',14,'La moyenne de deux notes est leur somme divisée par deux. En JavaScript, les parenthèses rendent explicite la partie à calculer en premier.

Sans parenthèses, 12 + 16 / 2 donne 20, car la division passe avant l’addition. Ce résultat est valide en syntaxe, mais ne correspond pas à la moyenne voulue.','const moyenne = (12 + 16) / 2;
console.log(moyenne);','Sélectionne l’expression qui calcule la moyenne de a et b.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
