insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-015','module-02','Convertir un prix avant le calcul','exercise',15,'Un prix reçu comme texte peut sembler numérique, mais + peut alors réunir des caractères. Convertir explicitement avec Number permet de faire une addition arithmétique.

L’expression prixTexte + 2 donnerait le texte 102. La conversion doit avoir lieu avant l’addition; afficher la valeur ne change pas son type.','const prixTexte = "10";
const total = Number(prixTexte) + 2;
console.log(total);','Le prix est le texte `"10"`. Quelle expression donne le nombre 12 après ajout de 2 ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
