insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-016','module-02','Projet : préparer une invitation','project',16,'Une phrase modèle peut contenir des valeurs entre ${...}. On appelle cela une interpolation dans une chaîne entourée d’accent grave. Les valeurs apparaissent à leur place sans perdre les espaces écrits dans le modèle.

Les accents graves encadrent toute la phrase. ${prenom} est remplacé par Lina et ${places} par 2; les espaces et la ponctuation restent exactement à leur place.','const prenom = "Lina";
const places = 2;
console.log(`Bonjour ${prenom}, tu as ${places} places.`);','Quel délimiteur permet d’interpoler `${prenom}` dans une chaîne ?
Ordonne les morceaux du message d’invitation.
Quelle phrase correspond exactement aux valeurs données ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-strings-in-javascript','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
