insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-017','module-03','Classer les comparaisons','exercise',17,'Les comparaisons donnent un booléen : true si la relation est vraie, false sinon. > signifie « plus grand que », < signifie « plus petit que », et >= inclut aussi la valeur égale à la limite.

Une comparaison répond à une question sans modifier les valeurs. Les nombres des deux côtés sont ici du même type.','console.log(7 > 5);
console.log(3 < 2);','Classe chaque expression selon le booléen qu’elle produit.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
