do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-017' and version=2 and public_content<>'{"id":"mvp-017","version":2,"title":"Classer les comparaisons","theory":[{"type":"heading","level":2,"text":"Classer les comparaisons"},{"type":"paragraph","segments":[{"type":"text","text":"Les comparaisons donnent un booléen : "},{"type":"code","text":"true"},{"type":"text","text":" si la relation est vraie, "},{"type":"code","text":"false"},{"type":"text","text":" sinon. "},{"type":"code","text":">"},{"type":"text","text":" signifie « plus grand que », "},{"type":"code","text":"<"},{"type":"text","text":" signifie « plus petit que », et "},{"type":"code","text":">="},{"type":"text","text":" inclut aussi la valeur égale à la limite."}]},{"type":"code","language":"javascript","code":"console.log(7 > 5);\nconsole.log(3 < 2);","output":"true puis false"},{"type":"paragraph","segments":[{"type":"text","text":"Une comparaison répond à une question sans modifier les valeurs. Les nombres des deux côtés sont ici du même type."}]}],"interactions":[{"id":"comparaisons","prompt":"Classe chaque expression selon le booléen qu’elle produit.","definition":{"kind":"classify","items":[{"id":"grand","label":"7 > 5"},{"id":"egal-limite","label":"5 >= 5"},{"id":"petit","label":"2 < 1"}],"categories":[{"id":"vrai","label":"true"},{"id":"faux","label":"false"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-017 version 2'; end if; end $$;
