insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-018','module-03','Comparer valeur et type','exercise',18,'L’égalité stricte === vérifie à la fois la valeur et le type. Deux nombres égaux donnent true; des valeurs de types différents donnent false, même si elles se ressemblent à l’écran. La comparaison retourne un booléen, pas l’une des valeurs comparées.

La première comparaison est vraie, car les deux côtés valent le même nombre et sont des nombres. La seconde est fausse : un texte et un nombre restent de types différents.','console.log(4 === 4);
console.log("4" === 4);','Indique true ou false pour les deux comparaisons. Réponds avec ces mots.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
