do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-018' and version=2 and public_content<>'{"id":"mvp-018","version":2,"title":"Comparer valeur et type","theory":[{"type":"heading","level":2,"text":"Comparer valeur et type"},{"type":"paragraph","segments":[{"type":"text","text":"L’égalité stricte "},{"type":"code","text":"==="},{"type":"text","text":" vérifie à la fois la valeur et le type. Deux nombres égaux donnent "},{"type":"code","text":"true"},{"type":"text","text":"; des valeurs de types différents donnent "},{"type":"code","text":"false"},{"type":"text","text":", même si elles se ressemblent à l’écran. La comparaison retourne un booléen, pas l’une des valeurs comparées."}]},{"type":"code","language":"javascript","code":"console.log(4 === 4);\nconsole.log(\"4\" === 4);","output":"true puis false"},{"type":"paragraph","segments":[{"type":"text","text":"La première comparaison est vraie, car les deux côtés valent le même nombre et sont des nombres. La seconde est fausse : un texte et un nombre restent de types différents."}]}],"interactions":[{"id":"strict","prompt":"Indique true ou false pour les deux comparaisons. Réponds avec ces mots.","code":{"language":"javascript","code":"4 === 4\n\"4\" === 4"},"definition":{"kind":"trace","cells":[{"id":"meme","label":"Résultat de 4 === 4"},{"id":"type","label":"Résultat de \"4\" === 4"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-018 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-018',2,'{"id":"mvp-018","version":2,"title":"Comparer valeur et type","theory":[{"type":"heading","level":2,"text":"Comparer valeur et type"},{"type":"paragraph","segments":[{"type":"text","text":"L’égalité stricte "},{"type":"code","text":"==="},{"type":"text","text":" vérifie à la fois la valeur et le type. Deux nombres égaux donnent "},{"type":"code","text":"true"},{"type":"text","text":"; des valeurs de types différents donnent "},{"type":"code","text":"false"},{"type":"text","text":", même si elles se ressemblent à l’écran. La comparaison retourne un booléen, pas l’une des valeurs comparées."}]},{"type":"code","language":"javascript","code":"console.log(4 === 4);\nconsole.log(\"4\" === 4);","output":"true puis false"},{"type":"paragraph","segments":[{"type":"text","text":"La première comparaison est vraie, car les deux côtés valent le même nombre et sont des nombres. La seconde est fausse : un texte et un nombre restent de types différents."}]}],"interactions":[{"id":"strict","prompt":"Indique true ou false pour les deux comparaisons. Réponds avec ces mots.","code":{"language":"javascript","code":"4 === 4\n\"4\" === 4"},"definition":{"kind":"trace","cells":[{"id":"meme","label":"Résultat de 4 === 4"},{"id":"type","label":"Résultat de \"4\" === 4"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
