insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-019','module-03','Choisir == ou ===','exercise',19,'=== compare sans convertir les types. == peut convertir une valeur avant comparaison : par exemple, "4" == 4 vaut true, mais "4" === 4 vaut false. Pour vérifier valeur et type ensemble, préfère ===.

La conversion implicite de == peut surprendre. Lorsque la règle exige que les types correspondent, l’égalité stricte exprime cette intention clairement.','console.log("4" == 4);
console.log("4" === 4);','La consigne exige que la valeur et le type soient tous deux identiques. Quel opérateur convient ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
