insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-020','module-03','Assembler un if','exercise',20,'Une instruction if teste une condition avant son bloc. Si le test est vrai, le bloc s’exécute; s’il est faux, le bloc est sauté. Les accolades encadrent les lignes qui dépendent de ce test.

La condition est vraie pour -2, donc le message s’affiche. Si temperature vaut 4, la même ligne console.log est sautée.','const temperature = -2;
if (temperature < 0) {
  console.log("Gel");
}','Ordonne les trois lignes du bloc if pour tester la température avant d’afficher Gel.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
