insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-021','module-03','Suivre le chemin else','exercise',21,'Quand un test if vaut false, le bloc else offre un chemin de rechange. Il ne relance pas la comparaison; il s’exécute à la place du bloc vrai.

3 est sous le seuil 5, donc la condition échoue et seule la sortie À refaire apparaît.','const points = 3;
if (points >= 5) {
  console.log("Réussi");
} else {
  console.log("À refaire");
}','Avec points = 3, indique la valeur de la condition et le texte affiché.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
