insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-022','module-03','Combiner deux règles','exercise',22,'&& signifie « et » : les deux conditions doivent être vraies. || signifie « ou » : au moins une condition vraie suffit. Ces opérateurs combinent des booléens, ils ne remplacent pas les comparaisons.

Un adulte avec billet satisfait les deux règles. Si une seule règle devait suffire, on choisirait ||.','const age = 19;
const billet = true;
console.log(age >= 18 && billet);','Classe le connecteur qui correspond à chaque consigne.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
