insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-023','module-03','Comparer sans modifier','exercise',23,'Un seul = attribue une valeur; trois signes === vérifient si deux valeurs sont strictement égales. Dans un if, on veut généralement poser une question, pas remplacer une variable.

Le test lit codeSaisi sans changer son contenu. Une affectation écrite par erreur dans la condition exprimerait une autre opération.','const codeSaisi = 2468;
if (codeSaisi === 2468) console.log("Ouvert");','Remplace l’opérateur pour vérifier que codeSaisi vaut bien 2468.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
