insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-024','module-03','Projet : vérifier une admissibilité','project',24,'Pour accéder à une activité, une personne doit avoir au moins 16 ans et avoir une autorisation. >= inclut exactement 16; && exige les deux critères. Le parcours examine les règles avant la décision.

On teste d’abord chaque condition, puis on combine leurs booléens. Une personne de 16 ans avec autorisation est admissible; une personne sans autorisation ne l’est pas.','const age = 16;
const autorisation = true;
const admissible = age >= 16 && autorisation;
console.log(admissible);','Classe les éléments comme condition d’admission ou information sans effet sur la règle.
Quel connecteur impose que l’âge et l’autorisation soient tous deux valides ?
Avec age = 15 et autorisation = true, indique le booléen final.',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-comparison-and-boolean-operators','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
