insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-025','module-04','Reconnaître une fonction','exercise',25,'Une fonction regroupe des instructions sous un nom pour pouvoir les réutiliser. Sa déclaration décrit le travail; un appel, avec des parenthèses, demande de le faire.

La déclaration seule ne lance pas le bloc. saluer() est l’appel; il reçoit ici la valeur transmise par return.','function saluer() {
  return "Salut";
}
console.log(saluer());','Relie chaque élément à son rôle dans l’exemple.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
