insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-026','module-04','Distinguer paramètre et argument','exercise',26,'Un paramètre est le nom local placé dans la déclaration d’une fonction. Un argument est la valeur concrète fournie entre parenthèses lors de l’appel.

À chaque appel, la valeur fournie est associée au paramètre correspondant. Le paramètre sert ensuite dans le calcul; il ne désigne pas le résultat.

Les paramètres sont des noms locaux à la fonction. Les arguments sont les valeurs concrètes données à l’appel et se placent dans le même ordre.

Pour une fonction à deux entrées, soustraire(9, 2) donne a=9 et b=2. Tu choisis les noms des paramètres dans la déclaration; leur position permet de savoir quel argument chacun reçoit.','function doubler(nombre) {
  return nombre * 2;
}
doubler(4);','Pendant l’appel doubler(4), quelle valeur reçoit le paramètre nombre ? Réponds par un nombre.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
