do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-026' and version=2 and public_content<>'{"id":"mvp-026","version":2,"title":"Distinguer paramètre et argument","theory":[{"type":"heading","level":2,"text":"Distinguer paramètre et argument"},{"type":"paragraph","segments":[{"type":"text","text":"Un "},{"type":"strong","text":"paramètre"},{"type":"text","text":" est le nom local placé dans la déclaration d’une fonction. Un "},{"type":"strong","text":"argument"},{"type":"text","text":" est la valeur concrète fournie entre parenthèses lors de l’appel."}]},{"type":"code","language":"javascript","code":"function doubler(nombre) {\n  return nombre * 2;\n}\ndoubler(4);","output":"nombre reçoit l’argument 4; résultat : 8"},{"type":"paragraph","segments":[{"type":"text","text":"À chaque appel, la valeur fournie est associée au paramètre correspondant. Le paramètre sert ensuite dans le calcul; il ne désigne pas le résultat."}]},{"type":"heading","level":3,"text":"Chaque argument suit la place du paramètre"},{"type":"paragraph","segments":[{"type":"text","text":"Les paramètres sont des noms locaux à la fonction. Les arguments sont les valeurs concrètes données à l’appel et se placent dans le même ordre."}]},{"type":"paragraph","segments":[{"type":"text","text":"Pour une fonction à deux entrées, "},{"type":"code","text":"soustraire(9, 2)"},{"type":"text","text":" donne a=9 et b=2. Tu choisis les noms des paramètres dans la déclaration; leur position permet de savoir quel argument chacun reçoit."}]},{"type":"code","language":"javascript","code":"function soustraire(a, b) { return a - b; }\nconsole.log(soustraire(9, 2));","output":"7"}],"interactions":[{"id":"valeur","prompt":"Pendant l’appel doubler(4), quelle valeur reçoit le paramètre nombre ? Réponds par un nombre.","code":{"language":"javascript","code":"function doubler(nombre) { return nombre * 2; }\ndoubler(4);"},"definition":{"kind":"trace","cells":[{"id":"recu","label":"Valeur de nombre au début de l’appel"},{"id":"retour","label":"Valeur calculée par la fonction"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-026 version 2'; end if; end $$;
