insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-027','module-04','Transmettre une valeur avec return','exercise',27,'return termine l’appel courant et transmet une valeur à l’endroit où la fonction a été appelée. console.log affiche quelque chose, mais ne remplace pas cette transmission.

Sans return, une fonction ne transmet pas ce calcul : son résultat est undefined. Le code qui appelle la fonction ne peut pas récupérer une simple ligne affichée.

Dès qu’un return est exécuté, la fonction rend cette valeur et ne poursuit pas les instructions qui suivent dans le même appel.

L’appelant peut utiliser ce résultat dans une variable ou le passer à console.log. L’affichage, lui, ne crée pas de valeur de retour.','function ajouterUn(n) {
  return n + 1;
}
const resultat = ajouterUn(3);','Quel mot transmet le nombre calculé à resultat ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
