insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-028','module-04','Composer des appels de fonction','exercise',28,'Le résultat d’une fonction peut devenir l’argument d’une autre. Dans un appel imbriqué, on résout d’abord celui qui est le plus à l’intérieur, puis on transmet son résultat à l’appel extérieur.

L’appel intérieur donne 6. L’appel extérieur reçoit 6 et le double à nouveau; on ne saute pas l’un des deux appels.','function doubler(n) { return n * 2; }
console.log(doubler(doubler(3)));','Ordonne les étapes de calcul de doubler(doubler(3)).',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
