insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-029','module-04','Repérer une variable locale','exercise',29,'Une variable déclarée dans une fonction est locale : son nom est accessible dans cette fonction, mais pas à l’extérieur. Les accolades montrent le bloc dans lequel elle existe.

total est utilisé à l’intérieur de calculer. Une ligne placée après l’accolade de fin ne peut pas lire ce nom directement.

Une déclaration dans le bloc d’une fonction est accessible dans ce bloc et ses blocs intérieurs. Une variable déclarée à l’extérieur peut être lue dans la fonction, comme joueur dans l’exemple.

L’inverse ne fonctionne pas : le nom local total n’existe pas après l’accolade fermante. La portée concerne l’endroit où un nom peut être utilisé.','const joueur = "Mina";
function calculer() {
  const total = 5;
  console.log(joueur);
  return total;
}
console.log(calculer());','Classe chaque nom selon son lieu de déclaration.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
