e calculer"},{"id":"global","label":"const joueur déclaré avant function calculer"}],"categories":[{"id":"interne","label":"Déclaration à l’intérieur de calculer"},{"id":"externe","label":"Déclaration dans le bloc extérieur"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-029 version 2'; end if; end $$;
