insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-030','module-04','Retourner le calcul','exercise',30,'Écrire une expression dans une fonction ne suffit pas à la transmettre à l’appelant. Le mot return doit précéder la valeur que l’on veut renvoyer.

Le calcul peut être juste tout en laissant le résultat inaccessible si aucun return ne le précède. Le correctif porte sur la ligne du calcul, pas sur la formule.','function aireRectangle(largeur, hauteur) {
  return largeur * hauteur;
}
console.log(aireRectangle(3, 4));','Choisis le remplacement qui transmet l’aire calculée.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
