insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-031','module-04','Distinguer affichage et résultat','exercise',31,'Une fonction peut afficher une valeur avec console.log, la transmettre avec return, ou ne faire ni l’un ni l’autre. Si aucun return n’est exécuté, le résultat de l’appel est undefined.

L’affichage et le résultat sont deux effets différents. Affecter l’appel à une variable ne crée pas automatiquement un retour.','function montrer() { console.log(7); }
const valeur = montrer();','Classe l’effet de chaque fonction.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
