insert into public.hints(id,lesson_id,position,body) values ('mvp-031-v2-h2','mvp-031',2,'Sans `return`, l’appel renvoie `undefined`, même si `console.log` affiche 7.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-031' and version=2 and public_content<>'{"id":"mvp-031","version":2,"title":"Distinguer affichage et résultat","theory":[{"type":"heading","level":2,"text":"Distinguer affichage et résultat"},{"type":"paragraph","segments":[{"type":"text","text":"Une fonction peut afficher une valeur avec "},{"type":"code","text":"console.log"},{"type":"text","text":", la transmettre avec "},{"type":"code","text":"return"},{"type":"text","text":", ou ne faire ni l’un ni l’autre. Si aucun "},{"type":"code","text":"return"},{"type":"text","text":" n’est exécuté, le résultat de l’appel est "},{"type":"code","text":"undefined"},{"type":"text","text":"."}]},{"type":"code","language":"javascript","code":"function montrer() { console.log(7); }\nconst valeur = montrer();","output":"Affiche 7; valeur reçoit undefined"},{"type":"paragraph","segments":[{"type":"text","text":"L’affichage et le résultat sont deux effets différents. Affecter l’appel à une variable ne crée pas automatiquement un retour."}]}],"interactions":[{"id":"effets","prompt":"Classe l’effet de chaque fonction.","definition":{"kind":"classify","items":[{"id":"log","label":"console.log(7); sans return"},{"id":"return","label":"return 7; sans console.log"},{"id":"vide","label":"Bloc vide"}],"categories":[{"id":"affiche-undefined","label":"Affiche 7, retourne undefined"},{"id":"retour-7","label":"Retourne 7 sans affichage"},{"id":"rien-undefined","label":"N’affiche rien, retourne undefined"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-031 version 2'; end if; end $$;
