insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-032','module-04','Projet : convertir des degrés','project',32,'Pour convertir des degrés Celsius en Fahrenheit, on calcule C × 9 / 5 + 32. Une fonction reçoit la température comme argument et retourne le résultat calculé.

On associe la formule à sa fonction, on suit les opérations dans leur ordre, puis on vérifie le point de congélation : 0 °C correspond à 32 °F.','function enFahrenheit(celsius) {
  return celsius * 9 / 5 + 32;
}
console.log(enFahrenheit(0));','Associe chaque élément de la conversion à son rôle.
Ordonne les opérations de la formule pour C = 0.
Indique les résultats intermédiaires pour 0 °C.
Quelle valeur la fonction retourne-t-elle pour 0 °C ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-functions','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
