insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-033','module-05','Écrire un tableau','exercise',33,'Un tableau regroupe plusieurs valeurs dans un ordre précis. On l’écrit entre crochets []; les virgules séparent ses éléments. Le nom du tableau permet de retrouver la collection entière.

Les crochets indiquent un tableau; les accolades servent à d’autres structures vues plus tard. Ici, l’ordre bleu, vert, rouge fait partie des données.','const couleurs = ["bleu", "vert", "rouge"];
console.log(couleurs);','Ordonne les morceaux pour déclarer couleurs avec bleu puis vert.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
