insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-034','module-05','Lire une valeur à son index','exercise',34,'L’index d’un tableau commence à 0. Dans ["rouge", "bleu", "vert"], l’index 0 désigne rouge, 1 désigne bleu et 2 désigne vert.

Un index est une position, pas un rang de départ à un. Le premier élément se lit avec [0].','const couleurs = ["rouge", "bleu", "vert"];
console.log(couleurs[1]);','Quelle valeur se trouve à l’index 2 ? Réponds par le texte sans guillemets.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
