insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-035','module-05','Modifier une case déclarée avec const','exercise',35,'const empêche de remplacer le tableau entier par une autre valeur, mais les cases d’un tableau restent modifiables. On peut donc mettre à jour un élément en utilisant son index.

Le nom couleurs désigne toujours le même tableau; seule la valeur de sa case 0 change. Cette règle concerne une mutation à une case précise, pas une nouvelle affectation de couleurs.','const couleurs = ["bleu", "vert"];
couleurs[0] = "jaune";
console.log(couleurs[0]);','Après l’affectation, quelle valeur contient couleurs[0] ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
