insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-036','module-05','Copier avant d’ajouter','exercise',36,'push ajoute une valeur à la fin du tableau sur lequel on l’appelle. Pour garder le tableau reçu intact, on peut créer une copie avec [...articles], puis ajouter à cette nouvelle collection.

Les trois points ... reprennent les éléments de entree dans un nouveau tableau. push modifie ensuite sortie; il ne modifie pas entree.

[...entree] crée un nouveau tableau avec les mêmes textes ou nombres, dans le même ordre. L’exemple porte sur ces valeurs simples : ajouter un élément à sortie ne modifie pas entree.','const entree = ["thé"];
const sortie = [...entree];
sortie.push("lait");','Ordonne copie, ajout et retour afin de préserver le tableau reçu.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
