insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-037','module-05','Retirer au début ou à la fin','exercise',37,'pop() enlève le dernier élément du tableau et le renvoie. shift() enlève plutôt le premier. Les deux modifient le tableau; le nom de l’opération indique de quel côté retirer.

Après pop, B reste avant C, puis le premier élément restant est B; dans cet exemple, shift est appliqué après pop. L’état final contient donc seulement B.','const file = ["A", "B", "C"];
const dernier = file.pop();
const premier = file.shift();','Quel élément chaque instruction retire-t-elle, dans cet ordre ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
