insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-038','module-05','Trouver le dernier élément','exercise',38,'length donne le nombre d’éléments. Comme le premier index vaut 0, le dernier index est length - 1. Un tableau vide n’a aucun index de dernier élément; on peut alors choisir une valeur spéciale comme null.

Ici, length vaut 3 et le dernier index vaut 2. Lire notes[3] dépasserait la dernière position valide.','const notes = [12, 15, 18];
console.log(notes[notes.length - 1]);','Quel résultat renvoyer pour un tableau vide; sinon, quel index lire ?',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
