insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-039','module-05','Reconnaître un index valide','exercise',39,'Pour un tableau de longueur n, les index valides vont de 0 à n - 1. Une position égale à length est déjà après le dernier élément et renvoie undefined dans ce cas simple.

La longueur vaut 3; seuls les index 0, 1 et 2 désignent une valeur. Vérifier la borne évite de lire une position absente.','const outils = ["éditeur", "terminal", "navigateur"];
console.log(outils[3]);','Classe chaque index pour outils, qui contient trois éléments.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
