insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-040','module-05','Projet : calculer un panier','project',40,'Un tableau de prix permet de garder un article par position. Pour trois articles connus, on peut lire les trois cases et additionner leurs valeurs sans boucle. push et pop ajoutent ou retirent un article si le panier change.

Ce panier comporte exactement trois prix. On lit chaque case et on additionne les montants; on ne divise pas le total. Comme le nombre d’articles est fixé à trois, on peut écrire les trois lectures directement.','const prix = [4, 3, 2];
const total = prix[0] + prix[1] + prix[2];
console.log(total);','Complète chaque lecture avec le bon index du tableau.
Indique le total après chaque addition. Réponds en nombres.
Ordonne la préparation, le calcul des trois prix, puis l’affichage.',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-arrays','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
