e la préparation, le calcul des trois prix, puis l’affichage.","definition":{"kind":"ordering","items":[{"id":"sum","label":"Calculer prix[0] + prix[1] + prix[2]"},{"id":"setup","label":"Déclarer le tableau des trois prix"},{"id":"show","label":"Afficher le total obtenu"}]}}],"project":{"steps":["cases","ordre","total"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-040 version 2'; end if; end $$;
