insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-041','module-06','Suivre les étapes d’une boucle','exercise',41,'Une boucle répète des instructions. Une boucle for initialise souvent un compteur, teste une condition avant chaque tour, exécute le corps, puis met le compteur à jour.

Après le corps, i++ ajoute 1. Le test est refait avant le tour suivant; quand il devient faux à i = 2, la boucle s’arrête.

Au début, i vaut 0 : le test i < 2 est vrai et le corps affiche 0. La mise à jour donne ensuite i=1; le test est vrai une deuxième fois et le corps affiche 1.

Après ce tour, i vaut 2. Le test 2 < 2 est faux : la boucle s’arrête sans afficher 2. L’initialisation ne se répète pas.','for (let i = 0; i < 2; i++) {
  console.log(i);
}','Ordonne l’initialisation, le test, le corps et la mise à jour d’un tour.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
