insert into public.hints(id,lesson_id,position,body) values ('mvp-041-v2-h2','mvp-041',2,'Le corps vient après le test; la mise à jour se fait avant le test suivant.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-041' and version=2 and public_content<>'{"id":"mvp-041","version":2,"title":"Suivre les étapes d’une boucle","theory":[{"type":"heading","level":2,"text":"Suivre les étapes d’une boucle"},{"type":"paragraph","segments":[{"type":"text","text":"Une boucle répète des instructions. Une boucle "},{"type":"code","text":"for"},{"type":"text","text":" initialise souvent un compteur, teste une condition avant chaque tour, exécute le corps, puis met le compteur à jour."}]},{"type":"code","language":"javascript","code":"for (let i = 0; i < 2; i++) {\n  console.log(i);\n}","output":"0 puis 1"},{"type":"paragraph","segments":[{"type":"text","text":"Après le corps, "},{"type":"code","text":"i++"},{"type":"text","text":" ajoute 1. Le test est refait avant le tour suivant; quand il devient faux à i = 2, la boucle s’arrête."}]},{"type":"heading","level":3,"text":"Lire les tours un à un"},{"type":"paragraph","segments":[{"type":"text","text":"Au début, i vaut 0 : le test "},{"type":"code","text":"i < 2"},{"type":"text","text":" est vrai et le corps affiche 0. La mise à jour donne ensuite i=1; le test est vrai une deuxième fois et le corps affiche 1."}]},{"type":"paragraph","segments":[{"type":"text","text":"Après ce tour, i vaut 2. Le test "},{"type":"code","text":"2 < 2"},{"type":"text","text":" est faux : la boucle s’arrête sans afficher 2. L’initialisation ne se répète pas."}]},{"type":"code","language":"javascript","code":"for (let i = 0; i < 3; i++) {\n  console.log(i);\n}","output":"0, puis 1, puis 2"}],"interactions":[{"id":"etapes","prompt":"Ordonne l’initialisation, le test, le corps et la mise à jour d’un tour.","definition":{"kind":"ordering","items":[{"id":"body","label":"Exécuter le corps"},{"id":"update","label":"Mettre à jour le compteur"},{"id":"start","label":"Initialiser le compteur"},{"id":"test","label":"Tester la condition"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-041 version 2'; end if; end $$;
