insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-042','module-06','Lire les parties de for','exercise',42,'Dans for (let i = 0; i < limite; i++), la première partie donne le départ, la deuxième répond « encore un tour ? », et la troisième fait avancer le compteur.

La limite 3 est exclue par <. Le compteur vaut successivement 0, 1 et 2; à 3, le test échoue.','for (let i = 0; i < 3; i++) {
  console.log(i);
}','Associe chaque partie de la boucle à son rôle.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
