insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-043','module-06','Faire progresser une boucle while','exercise',43,'Une boucle while recommence tant que sa condition est vraie. Il faut modifier une valeur testée pour qu’elle se rapproche de l’arrêt; sinon, le test peut rester vrai indéfiniment.

Comme la condition est essais < 3, augmenter essais finit par la rendre fausse. Le faire diminuer l’éloignerait de la limite.','let essais = 0;
while (essais < 3) {
  essais++;
}','Quel changement fait avancer essais vers la fin prévue ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
