insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-044','module-06','Additionner avec un accumulateur','exercise',44,'Un accumulateur garde un total qui évolue pendant les tours d’une boucle. Avec for...of, la variable prend successivement chaque élément du tableau; le total doit rester déclaré avant la boucle.

total += note est une écriture courte de total = total + note. Le total passe de 0 à 2, puis 6, puis 12. On divise enfin par les trois notes; réinitialiser total à l’intérieur de la boucle ferait perdre les additions précédentes.

total += note est l’abréviation de total = total + note. Il reprend donc la valeur précédente du total, lui ajoute la note du tour et range le nouveau résultat.

Déclare le total avant la boucle. Si tu le remets à zéro dans le corps, chaque tour efface la somme précédente. La moyenne se calcule après la boucle avec le nombre d’éléments.','const notes = [2, 4, 6];
let total = 0;
for (const note of notes) total += note;
const moyenne = total / notes.length;','Indique total après chaque élément, puis la moyenne. Réponds avec des nombres.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
