do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-044' and version=2 and public_content<>'{"id":"mvp-044","version":2,"title":"Additionner avec un accumulateur","theory":[{"type":"heading","level":2,"text":"Additionner avec un accumulateur"},{"type":"paragraph","segments":[{"type":"text","text":"Un "},{"type":"strong","text":"accumulateur"},{"type":"text","text":" garde un total qui évolue pendant les tours d’une boucle. Avec "},{"type":"code","text":"for...of"},{"type":"text","text":", la variable prend successivement chaque élément du tableau; le total doit rester déclaré avant la boucle."}]},{"type":"code","language":"javascript","code":"const notes = [2, 4, 6];\nlet total = 0;\nfor (const note of notes) total += note;\nconst moyenne = total / notes.length;","output":"total = 12; moyenne = 4"},{"type":"paragraph","segments":[{"type":"code","text":"total += note"},{"type":"text","text":" est une écriture courte de "},{"type":"code","text":"total = total + note"},{"type":"text","text":". Le total passe de 0 à 2, puis 6, puis 12. On divise enfin par les trois notes; réinitialiser total à l’intérieur de la boucle ferait perdre les additions précédentes."}]},{"type":"heading","level":3,"text":"Un accumulateur garde son état"},{"type":"paragraph","segments":[{"type":"code","text":"total += note"},{"type":"text","text":" est l’abréviation de "},{"type":"code","text":"total = total + note"},{"type":"text","text":". Il reprend donc la valeur précédente du total, lui ajoute la note du tour et range le nouveau résultat."}]},{"type":"paragraph","segments":[{"type":"text","text":"Déclare le total avant la boucle. Si tu le remets à zéro dans le corps, chaque tour efface la somme précédente. La moyenne se calcule après la boucle avec le nombre d’éléments."}]},{"type":"code","language":"javascript","code":"let total = 0;\nfor (const note of [2, 4]) total += note;\nconsole.log(total / 2);","output":"3"}],"interactions":[{"id":"total","prompt":"Indique total après chaque élément, puis la moyenne. Réponds avec des nombres.","definition":{"kind":"trace","cells":[{"id":"apres2","label":"Après la note 2"},{"id":"apres4","label":"Après la note 4"},{"id":"apres6","label":"Après la note 6"},{"id":"moyenne","label":"Total divisé par 3"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-044 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-044',2,'{"id":"mvp-044","version":2,"title":"Additionner avec un accumulateur","theory":[{"type":"heading","level":2,"text":"Additionner avec un accumulateur"},{"type":"paragraph","segments":[{"type":"text","text":"Un "},{"type":"strong","text":"accumulateur"},{"type":"text","text":" garde un total qui évolue pendant les tours d’une boucle. Avec "},{"type":"code","text":"for...of"},{"type":"text","text":", la variable prend successivement chaque élément du tableau; le total doit rester déclaré avant la boucle."}]},{"type":"code","language":"javascript","code":"const notes = [2, 4, 6];\nlet total = 0;\nfor (const note of notes) total += note;\nconst moyenne = total / notes.length;","output":"total = 12; moyenne = 4"},{"type":"paragraph","segments":[{"type":"code","text":"total += note"},{"type":"text","text":" est une écriture courte de "},{"type":"code","text":"total = total + note"},{"type":"text","text":". Le total passe de 0 à 2, puis 6, puis 12. On divise enfin par les trois notes; réinitialiser total à l’intérieur de la boucle ferait perdre les additions précédentes."}]},{"type":"heading","level":3,"text":"Un accumulateur garde son état"},{"type":"paragraph","segments":[{"type":"code","text":"total += note"},{"type":"text","text":" est l’abréviation de "},{"type":"code","text":"total = total + note"},{"type":"text","text":". Il reprend donc la valeur précédente du total, lui ajoute la note du tour et range le nouveau résultat."}]},{"type":"paragraph","segments":[{"type":"text","text":"Déclare le total avant la boucle. Si tu le remets à zéro dans le corps, chaque tour efface la somme précédente. La moyenne se calcule après la boucle avec le nombre d’éléments."}]},{"type":"code","language":"javascript","code":"let total = 0;\nfor (const note of [2, 4]) total += note;\nconsole.log(total / 2);","output":"3"}],"interactions":[{"id":"total","prompt":"Indique total après chaque élément, puis la moyenne. Réponds avec des nombres.","definition":{"kind":"trace","cells":[{"id":"apres2","label":"Après la note 2"},{"id":"apres4","label":"Après la note 4"},{"id":"apres6","label":"Après la note 6"},{"id":"moyenne","label":"Total divisé par 3"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
