insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-045','module-06','Comprendre break','exercise',45,'break arrête immédiatement la boucle la plus proche. Les lignes placées après lui dans le même tour ne s’exécutent pas, et aucun nouveau tour ne commence.

Au premier tour, 1 est affiché. Au suivant, i vaut 2 et break arrête la boucle avant console.log(i).','for (let i = 1; i <= 3; i++) {
  if (i === 2) break;
  console.log(i);
}','Quelles valeurs sont affichées avant l’arrêt ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
