insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-046','module-06','Réparer une progression qui s’éloigne','exercise',46,'Pour terminer une boucle, la mise à jour doit rapprocher le compteur de la condition d’arrêt. On peut vérifier cela sur papier sans lancer le code.

Depuis 0, soustraire 1 éloigne i de 3. Un incrément le fait passer à 1, puis 2, puis 3, où le test s’arrête.','let i = 0;
while (i < 3) {
  i--;
}','Remplace la mise à jour pour que le compteur atteigne la limite 3.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
