insert into public.hints(id,lesson_id,position,body) values ('mvp-046-v2-h2','mvp-046',2,'La mise à jour doit le rapprocher du moment où la condition devient fausse.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-046' and version=2 and public_content<>'{"id":"mvp-046","version":2,"title":"Réparer une progression qui s’éloigne","theory":[{"type":"heading","level":2,"text":"Réparer une progression qui s’éloigne"},{"type":"paragraph","segments":[{"type":"text","text":"Pour terminer une boucle, la mise à jour doit rapprocher le compteur de la condition d’arrêt. On peut vérifier cela sur papier sans lancer le code."}]},{"type":"code","language":"javascript","code":"let i = 0;\nwhile (i < 3) {\n  i--;\n}","output":"Le compteur descend; la condition reste vraie."},{"type":"paragraph","segments":[{"type":"text","text":"Depuis 0, soustraire 1 éloigne i de 3. Un incrément le fait passer à 1, puis 2, puis 3, où le test s’arrête."}]}],"interactions":[{"id":"reparation","prompt":"Remplace la mise à jour pour que le compteur atteigne la limite 3.","definition":{"kind":"debug","lines":[{"id":"ligne","text":"i--;"}],"replacements":[{"id":"plus","text":"i++;"},{"id":"moins","text":"i -= 2;"},{"id":"pareil","text":"i = i;"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-046 version 2'; end if; end $$;
