insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-047','module-06','Choisir une borne sans dépasser','exercise',47,'Pour visiter chaque index d’un tableau, la boucle commence à 0 et s’arrête avant length. La condition i < length exclut la position qui n’existe pas.

La longueur vaut 2; les index valides sont 0 et 1. Avec i <= length, la boucle tenterait aussi l’index 2.','const noms = ["Ana", "Malik"];
for (let i = 0; i < noms.length; i++) console.log(noms[i]);','Quelle condition visite les index valides sans inclure length ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
