insert into public.hints(id,lesson_id,position,body) values ('mvp-047-v2-h1','mvp-047',1,'Le dernier élément est à `length - 1`.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-047-v2-h2','mvp-047',2,'La borne `i < length` s’arrête avant la première position absente.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-047' and version=2 and public_content<>'{"id":"mvp-047","version":2,"title":"Choisir une borne sans dépasser","theory":[{"type":"heading","level":2,"text":"Choisir une borne sans dépasser"},{"type":"paragraph","segments":[{"type":"text","text":"Pour visiter chaque index d’un tableau, la boucle commence à 0 et s’arrête avant "},{"type":"code","text":"length"},{"type":"text","text":". La condition "},{"type":"code","text":"i < length"},{"type":"text","text":" exclut la position qui n’existe pas."}]},{"type":"code","language":"javascript","code":"const noms = [\"Ana\", \"Malik\"];\nfor (let i = 0; i < noms.length; i++) console.log(noms[i]);","output":"Ana puis Malik"},{"type":"paragraph","segments":[{"type":"text","text":"La longueur vaut 2; les index valides sont 0 et 1. Avec "},{"type":"code","text":"i <= length"},{"type":"text","text":", la boucle tenterait aussi l’index 2."}]}],"interactions":[{"id":"borne","prompt":"Quelle condition visite les index valides sans inclure length ?","definition":{"kind":"choice","mode":"single","options":[{"id":"strict","label":"i < noms.length"},{"id":"inclusif","label":"i <= noms.length"},{"id":"depart","label":"i > 0"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-047 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-047',2,'{"id":"mvp-047","version":2,"title":"Choisir une borne sans dépasser","theory":[{"type":"heading","level":2,"text":"Choisir une borne sans dépasser"},{"type":"paragraph","segments":[{"type":"text","text":"Pour visiter chaque index d’un tableau, la boucle commence à 0 et s’arrête avant "},{"type":"code","text":"length"},{"type":"text","text":". La condition "},{"type":"code","text":"i < length"},{"type":"text","text":" exclut la position qui n’existe pas."}]},{"type":"code","language":"javascript","code":"const noms = [\"Ana\", \"Malik\"];\nfor (let i = 0; i < noms.length; i++) console.log(noms[i]);","output":"Ana puis Malik"},{"type":"paragraph","segments":[{"type":"text","text":"La longueur vaut 2; les index valides sont 0 et 1. Avec "},{"type":"code","text":"i <= length"},{"type":"text","text":", la boucle tenterait aussi l’index 2."}]}],"interactions":[{"id":"borne","prompt":"Quelle condition visite les index valides sans inclure length ?","definition":{"kind":"choice","mode":"single","options":[{"id":"strict","label":"i < noms.length"},{"id":"inclusif","label":"i <= noms.length"},{"id":"depart","label":"i > 0"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
