insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-048','module-06','Projet : garder les nombres positifs','project',48,'Un filtre parcourt les valeurs dans leur ordre et conserve seulement celles qui satisfont une condition. « Strictement positif » signifie supérieur à zéro; zéro doit donc être écarté.

On crée un tableau de résultat, on teste chaque nombre, puis on ajoute seulement les valeurs retenues. L’ordre d’origine est conservé; le résultat ne contient aucun trou.','const notes = [-2, 0, 3, 5];
const positives = [];
for (const n of notes) {
  if (n > 0) positives.push(n);
}','Classe les nombres selon le filtre n > 0.
Ordonne les étapes du filtrage.
Quelles valeurs restent après le filtre ? Écris-les dans l’ordre, séparées par une virgule.
Quelle règle explique pourquoi 0 n’apparaît pas ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-loops','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
