es nombres négatifs"},{"id":"tri","label":"Le résultat est trié et zéro disparaît"}]}}],"project":{"steps":["regle","ordre","trace","validation"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-048 version 2'; end if; end $$;
