insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-049','module-07','Reconnaître un objet','exercise',49,'Un objet rassemble des informations sous des noms appelés propriétés. Chaque propriété associe une clé écrite et une valeur. Contrairement à un tableau, on lit une propriété par son nom et non par une position numérique.

Dans cet objet, pseudo et score sont les clés; Mina et 7 sont leurs valeurs. La notation avec un point demande la valeur liée au nom qui suit.','const joueur = { pseudo: "Mina", score: 7 };
console.log(joueur.pseudo);','Associe chaque clé à sa valeur dans joueur.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
