insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-050','module-07','Lire et modifier une propriété','exercise',50,'La notation joueur.score lit la propriété nommée score. Quand joueur.score est à gauche de =, son affectation remplace cette valeur. Ici, le point donne un nom de propriété; dans un tableau, les crochets contiennent un index numérique. Les objets peuvent aussi utiliser des crochets pour lire une propriété.

L’objet garde ses deux propriétés, mais score vaut maintenant 8. On n’a pas lu une case numéro 8; on a changé la valeur associée au nom score.','const joueur = { pseudo: "Mina", score: 7 };
joueur.score = 8;
console.log(joueur.score);','Quelle propriété faut-il lire pour afficher le pseudo ?
Après la modification, indique le pseudo et le score de joueur.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
