insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-051','module-07','Distinguer pile et file','exercise',51,'Une pile fonctionne comme les assiettes empilées : la dernière posée est la première reprise (LIFO). Une file suit l’ordre d’arrivée : la première personne arrivée passe d’abord (FIFO).

push ajoute à la fin d’un tableau et pop retire cette dernière valeur. Une file retire plutôt le premier élément, avec shift; elle conserve ainsi l’ordre d’arrivée.','const pile = ["A", "B"];
pile.push("C");
pile.pop();','Associe chaque situation à la structure adaptée.
Dans la pile A, B puis C, quelle valeur sort avec pop ? Et dans une file A, B puis C, laquelle sort avec shift ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
