insert into public.hints(id,lesson_id,position,body) values ('mvp-051-v2-h2','mvp-051',2,'La pile retire le dernier arrivé; la file retire le premier arrivé.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-051' and version=2 and public_content<>'{"id":"mvp-051","version":2,"title":"Distinguer pile et file","theory":[{"type":"heading","level":2,"text":"Distinguer pile et file"},{"type":"paragraph","segments":[{"type":"text","text":"Une "},{"type":"strong","text":"pile"},{"type":"text","text":" fonctionne comme les assiettes empilées : la dernière posée est la première reprise (LIFO). Une "},{"type":"strong","text":"file"},{"type":"text","text":" suit l’ordre d’arrivée : la première personne arrivée passe d’abord (FIFO)."}]},{"type":"code","language":"javascript","code":"const pile = [\"A\", \"B\"];\npile.push(\"C\");\npile.pop();","output":"La pile retrouve C en premier"},{"type":"paragraph","segments":[{"type":"code","text":"push"},{"type":"text","text":" ajoute à la fin d’un tableau et "},{"type":"code","text":"pop"},{"type":"text","text":" retire cette dernière valeur. Une file retire plutôt le premier élément, avec "},{"type":"code","text":"shift"},{"type":"text","text":"; elle conserve ainsi l’ordre d’arrivée."}]}],"interactions":[{"id":"situations","prompt":"Associe chaque situation à la structure adaptée.","definition":{"kind":"matching","left":[{"id":"assiettes","label":"Retirer l’assiette posée en dernier"},{"id":"attente","label":"Servir la première personne arrivée"}],"right":[{"id":"pile","label":"Pile LIFO"},{"id":"file","label":"File FIFO"}],"oneToOne":true}},{"id":"retrait","prompt":"Dans la pile A, B puis C, quelle valeur sort avec pop ? Et dans une file A, B puis C, laquelle sort avec shift ?","definition":{"kind":"trace","cells":[{"id":"pile","label":"Valeur retirée de la pile"},{"id":"file","label":"Valeur retirée de la file"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-051 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-051',2,'{"id":"mvp-051","version":2,"title":"Distinguer pile et file","theory":[{"type":"heading","level":2,"text":"Distinguer pile et file"},{"type":"paragraph","segments":[{"type":"text","text":"Une "},{"type":"strong","text":"pile"},{"type":"text","text":" fonctionne comme les assiettes empilées : la dernière posée est la première reprise (LIFO). Une "},{"type":"strong","text":"file"},{"type":"text","text":" suit l’ordre d’arrivée : la première personne arrivée passe d’abord (FIFO)."}]},{"type":"code","language":"javascript","code":"const pile = [\"A\", \"B\"];\npile.push(\"C\");\npile.pop();","output":"La pile retrouve C en premier"},{"type":"paragraph","segments":[{"type":"code","text":"push"},{"type":"text","text":" ajoute à la fin d’un tableau et "},{"type":"code","text":"pop"},{"type":"text","text":" retire cette dernière valeur. Une file retire plutôt le premier élément, avec "},{"type":"code","text":"shift"},{"type":"text","text":"; elle conserve ainsi l’ordre d’arrivée."}]}],"interactions":[{"id":"situations","prompt":"Associe chaque situation à la structure adaptée.","definition":{"kind":"matching","left":[{"id":"assiettes","label":"Retirer l’assiette posée en dernier"},{"id":"attente","label":"Servir la première personne arrivée"}],"right":[{"id":"pile","label":"Pile LIFO"},{"id":"file","label":"File FIFO"}],"oneToOne":true}},{"id":"retrait","prompt":"Dans la pile A, B puis C, quelle valeur sort avec pop ? Et dans une file A, B puis C, laquelle sort avec shift ?","definition":{"kind":"trace","cells":[{"id":"pile","label":"Valeur retirée de la pile"},{"id":"file","label":"Valeur retirée de la file"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
