insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-052','module-07','Créer un ensemble sans doublons','exercise',52,'new Set(nombres) crée un ensemble à partir du tableau. Un Set ne garde qu’une occurrence de chaque valeur; il ne trie pas et conserve l’ordre de première apparition.

Le deuxième 3 disparaît; 1 et 2 restent après leur première apparition. Les trois points recopient les éléments de l’ensemble dans un nouveau tableau.','const nombres = [3, 1, 3, 2];
const uniques = [...new Set(nombres)];','Ordonne la création du Set puis du tableau unique.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
