insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-053','module-07','Utiliser set, get et has avec Map','exercise',53,'new Map() crée une collection d’associations entre des clés et des valeurs. set(clé, valeur) écrit ou remplace une association, get(clé) lit la valeur et has(clé) renvoie un booléen qui indique si la clé existe.

get ne crée pas une association; il lit celle qui a été ajoutée avec set. has est utile pour vérifier une clé avant de lire sa valeur.

get lit la valeur associée à une clé; il ne crée pas la clé. Pour une clé absente, get renvoie undefined.

has donne un booléen qui permet de vérifier la présence avant une lecture. new Map() crée une Map vide; set ajoute ensuite des associations.','const scores = new Map();
scores.set("Mina", 7);
console.log(scores.get("Mina"));
console.log(scores.has("Mina"));','Associe chaque action au verbe de Map correspondant.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
