do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-053' and version=2 and public_content<>'{"id":"mvp-053","version":2,"title":"Utiliser set, get et has avec Map","theory":[{"type":"heading","level":2,"text":"Utiliser set, get et has avec Map"},{"type":"paragraph","segments":[{"type":"code","text":"new Map()"},{"type":"text","text":" crée une collection d’associations entre des clés et des valeurs. "},{"type":"code","text":"set(clé, valeur)"},{"type":"text","text":" écrit ou remplace une association, "},{"type":"code","text":"get(clé)"},{"type":"text","text":" lit la valeur et "},{"type":"code","text":"has(clé)"},{"type":"text","text":" renvoie un booléen qui indique si la clé existe."}]},{"type":"code","language":"javascript","code":"const scores = new Map();\nscores.set(\"Mina\", 7);\nconsole.log(scores.get(\"Mina\"));\nconsole.log(scores.has(\"Mina\"));","output":"7 puis true"},{"type":"paragraph","segments":[{"type":"code","text":"get"},{"type":"text","text":" ne crée pas une association; il lit celle qui a été ajoutée avec "},{"type":"code","text":"set"},{"type":"text","text":". "},{"type":"code","text":"has"},{"type":"text","text":" est utile pour vérifier une clé avant de lire sa valeur."}]},{"type":"heading","level":3,"text":"Lire une clé présente ou absente"},{"type":"paragraph","segments":[{"type":"code","text":"get"},{"type":"text","text":" lit la valeur associée à une clé; il ne crée pas la clé. Pour une clé absente, "},{"type":"code","text":"get"},{"type":"text","text":" renvoie "},{"type":"code","text":"undefined"},{"type":"text","text":"."}]},{"type":"paragraph","segments":[{"type":"code","text":"has"},{"type":"text","text":" donne un booléen qui permet de vérifier la présence avant une lecture. "},{"type":"code","text":"new Map()"},{"type":"text","text":" crée une Map vide; "},{"type":"code","text":"set"},{"type":"text","text":" ajoute ensuite des associations."}]},{"type":"code","language":"javascript","code":"const scores = new Map();\nscores.set(\"Mina\", 7);\nconsole.log(scores.has(\"Mina\"));\nconsole.log(scores.get(\"Lina\"));","output":"true puis undefined"}],"interactions":[{"id":"actions","prompt":"Associe chaque action au verbe de Map correspondant.","definition":{"kind":"matching","left":[{"id":"ecrire","label":"Associer Mina à 7"},{"id":"lire","label":"Récupérer la valeur de Mina"},{"id":"verifier","label":"Tester si Mina est déjà une clé"}],"right":[{"id":"set","label":"set"},{"id":"get","label":"get"},{"id":"has","label":"has"}],"oneToOne":true}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-053 version 2'; end if; end $$;
