insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-054','module-07','Ne pas rejeter l’index zéro','exercise',54,'indexOf(valeur) renvoie la position de la première occurrence, ou -1 si la valeur est absente. L’index 0 est une position valide; il ne faut donc pas confondre zéro avec l’absence.

La réponse 0 signifie que fr est au début du tableau. Seul -1 indique que la recherche n’a rien trouvé.','const langues = ["fr", "en"];
console.log(langues.indexOf("fr"));','Remplace > 0 pour que l’index 0 soit accepté comme une présence.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
