insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-055','module-07','Comparer accès direct et parcours','exercise',55,'La notation O(1) décrit un travail qui reste constant quand la collection grandit; O(n) décrit un travail qui augmente avec le nombre d’éléments. Ce sont des tendances de croissance, pas des durées exactes.

Avec 100 éléments, lire l’index 0 demande toujours une lecture. Chercher le dernier élément peut examiner 100 positions; si la liste passe à 200, ce parcours peut en examiner 200.','Accès à tableau[0] : 1 lecture.
Recherche séquentielle : jusqu’à n lectures.','Classe chaque opération selon son nombre de lectures quand la liste double.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
