insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-056','module-07','Projet : compter des mots','project',56,'Une Map peut conserver le nombre d’apparitions de chaque mot. Pour le premier mot, has répond false et le compteur commence à 0. get lit ensuite la valeur existante; set enregistre son augmentation.

Au premier chat, la clé n’existe pas : on enregistre 1. Le mot lune reçoit aussi 1; au retour de chat, get retrouve 1 et set stocke 2. has("lune") confirme ensuite que la clé existe.

La boucle for...of lit les mots dans l’ordre du tableau. Pour chaque mot, has indique s’il a déjà une entrée; si oui, get récupère le compte courant.

On ajoute 1 au compte et set enregistre sa nouvelle valeur. Une Map conserve l’ordre où ses clés ont été ajoutées pour la première fois : une répétition modifie le compte sans déplacer la clé. Dans cet exemple, has("lune") vérifie la clé dont le nom est le texte lune.','const mots = ["chat", "lune", "chat"];
const comptes = new Map();
for (const mot of mots) {
  let actuel = 0;
  if (comptes.has(mot)) actuel = comptes.get(mot);
  comptes.set(mot, actuel + 1);
}
console.log(comptes.get("chat"));
console.log(comptes.has("lune"));','Associe la lecture et l’écriture du compteur Map à leur opération.
Trace les compteurs après chaque mot de la liste chat, lune, chat.
Ordonne les opérations pour traiter un mot déjà compté.
Quelle paire de compteurs décrit les trois mots ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-working-with-common-data-structures','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
