insert into public.hints(id,lesson_id,position,body) values ('mvp-056-v2-h1','mvp-056',1,'Pour un mot déjà vu, récupère le compte avant de l’incrémenter.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-056-v2-h2','mvp-056',2,'Pour un mot absent, pars de zéro; chaque nouvelle occurrence ajoute une unité.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-056' and version=2 and public_content<>'{"id":"mvp-056","version":2,"title":"Projet : compter des mots","theory":[{"type":"heading","level":2,"text":"Projet : compter des mots"},{"type":"paragraph","segments":[{"type":"text","text":"Une Map peut conserver le nombre d’apparitions de chaque mot. Pour le premier mot, "},{"type":"code","text":"has"},{"type":"text","text":" répond false et le compteur commence à 0. "},{"type":"code","text":"get"},{"type":"text","text":" lit ensuite la valeur existante; "},{"type":"code","text":"set"},{"type":"text","text":" enregistre son augmentation."}]},{"type":"code","language":"javascript","code":"const mots = [\"chat\", \"lune\", \"chat\"];\nconst comptes = new Map();\nfor (const mot of mots) {\n  let actuel = 0;\n  if (comptes.has(mot)) actuel = comptes.get(mot);\n  comptes.set(mot, actuel + 1);\n}\nconsole.log(comptes.get(\"chat\"));\nconsole.log(comptes.has(\"lune\"));","output":"2 puis true"},{"type":"paragraph","segments":[{"type":"text","text":"Au premier chat, la clé n’existe pas : on enregistre 1. Le mot lune reçoit aussi 1; au retour de chat, "},{"type":"code","text":"get"},{"type":"text","text":" retrouve 1 et "},{"type":"code","text":"set"},{"type":"text","text":" stocke 2. "},{"type":"code","text":"has(\"lune\")"},{"type":"text","text":" confirme ensuite que la clé existe."}]},{"type":"heading","level":3,"text":"Mettre à jour une fréquence"},{"type":"paragraph","segments":[{"type":"text","text":"La boucle "},{"type":"code","text":"for...of"},{"type":"text","text":" lit les mots dans l’ordre du tableau. Pour chaque mot, "},{"type":"code","text":"has"},{"type":"text","text":" indique s’il a déjà une entrée; si oui, "},{"type":"code","text":"get"},{"type":"text","text":" récupère le compte courant."}]},{"type":"paragraph","segments":[{"type":"text","text":"On ajoute 1 au compte et "},{"type":"code","text":"set"},{"type":"text","text":" enregistre sa nouvelle valeur. Une Map conserve l’ordre où ses clés ont été ajoutées pour la première fois : une répétition modifie le compte sans déplacer la clé. Dans cet exemple, "},{"type":"code","text":"has(\"lune\")"},{"type":"text","text":" vérifie la clé dont le nom est le texte "},{"type":"code","text":"lune"},{"type":"text","text":"."}]},{"type":"code","language":"javascript","code":"const comptes = new Map();\nfor (const mot of [\"chat\", \"chat\"]) {\n  let precedent = 0;\n  if (comptes.has(mot)) {\n    precedent = comptes.get(mot);\n  }\n  comptes.set(mot, precedent + 1);\n}\nconsole.log(comptes.get(\"chat\"));","output":"2"}],"interactions":[{"id":"actions","prompt":"Associe la lecture et l’écriture du compteur Map à leur opération.","definition":{"kind":"matching","left":[{"id":"lire","label":"Récupérer le nombre actuel"},{"id":"ecrire","label":"Enregistrer le nouveau nombre"}],"right":[{"id":"get","label":"get(mot)"},{"id":"set","label":"set(mot, nombre)"}],"oneToOne":true}},{"id":"compteurs","prompt":"Trace les compteurs après chaque mot de la liste chat, lune, chat.","definition":{"kind":"trace","cells":[{"id":"premier","label":"Après le premier chat : chat"},{"id":"deuxieme","label":"Après lune : lune"},{"id":"final","label":"Après le dernier chat : chat"}]}},{"id":"ordre","prompt":"Ordonne les opérations pour traiter un mot déjà compté.","definition":{"kind":"ordering","items":[{"id":"save","label":"Enregistrer le compteur augmenté"},{"id":"read","label":"Lire le compteur actuel"},{"id":"increment","label":"Ajouter 1"}]}},{"id":"resultat","prompt":"Quelle paire de compteurs décrit les trois mots ?","definition":{"kind":"choice","mode":"single","options":[{"id":"good","label":"chat : 2; lune : 1"},{"id":"reset","label":"chat : 1; lune : 1"},{"id":"reverse","label":"chat : 1; lune : 2"}]}}],"project":{"steps":["actions","compteurs","ordre","resultat"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-056 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-056',2,'{"id":"mvp-056","version":2,"title":"Projet : compter des mots","theory":[{"type":"heading","level":2,"text":"Projet : compter des mots"},{"type":"paragraph","segments":[{"type":"text","text":"Une Map peut conserver le nombre d’apparitions de chaque mot. Pour le premier mot, "},{"type":"code","text":"has"},{"type":"text","text":" répond false et le compteur commence à 0. "},{"type":"code","text":"get"},{"type":"text","text":" lit ensuite la valeur existante; "},{"type":"code","text":"set"},{"type":"text","text":" enregistre son augmentation."}]},{"type":"code","language":"javascript","code":"const mots = [\"chat\", \"lune\", \"chat\"];\nconst comptes = new Map();\nfor (const mot of mots) {\n  let actuel = 0;\n  if (comptes.has(mot)) actuel = comptes.get(mot);\n  comptes.set(mot, actuel + 1);\n}\nconsole.log(comptes.get(\"chat\"));\nconsole.log(comptes.has(\"lune\"));","output":"2 puis true"},{"type":"paragraph","segments":[{"type":"text","text":"Au premier chat, la clé n’existe pas : on enregistre 1. Le mot lune reçoit aussi 1; au retour de chat, "},{"type":"code","text":"get"},{"type":"text","text":" retrouve 1 et "},{"type":"code","text":"set"},{"type":"text","text":" stocke 2. "},{"type":"code","text":"has(\"lune\")"},{"type":"text","text":" confirme ensuite que la clé existe."}]},{"type":"heading","level":3,"text":"Mettre à jour une fréquence"},{"type":"paragraph","segments":[{"type":"text","text":"La boucle "},{"type":"code","text":"for...of"},{"type":"text","text":" lit les mots dans l’ordre du tableau. Pour chaque mot, "},{"type":"code","text":"has"},{"type":"text","text":" indique s’il a déjà une entrée; si oui, "},{"type":"code","text":"get"},{"type":"text","text":" récupère le compte courant."}]},{"type":"paragraph","segments":[{"type":"text","text":"On ajoute 1 au compte et "},{"type":"code","text":"set"},{"type":"text","text":" enregistre sa nouvelle valeur. Une Map conserve l’ordre où ses clés ont été ajoutées pour la première fois : une répétition modifie le compte sans déplacer la clé. Dans cet exemple, "},{"type":"code","text":"has(\"lune\")"},{"type":"text","text":" vérifie la clé dont le nom est le texte "},{"type":"code","text":"lune"},{"type":"text","text":"."}]},{"type":"code","language":"javascript","code":"const comptes = new Map();\nfor (const mot of [\"chat\", \"chat\"]) {\n  let precedent = 0;\n  if (comptes.has(mot)) {\n    precedent = comptes.get(mot);\n  }\n  comptes.set(mot, precedent + 1);\n}\nconsole.log(comptes.get(\"chat\"));","output":"2"}],"interactions":[{"id":"actions","prompt":"Associe la lecture et l’écriture du compteur Map à leur opération.","definition":{"kind":"matching","left":[{"id":"lire","label":"Récupérer le nombre actuel"},{"id":"ecrire","label":"Enregistrer le nouveau nombre"}],"right":[{"id":"get","label":"get(mot)"},{"id":"set","label":"set(mot, nombre)"}],"oneToOne":true}},{"id":"compteurs","prompt":"Trace les compteurs après chaque mot de la liste chat, lune, chat.","definition":{"kind":"trace","cells":[{"id":"premier","label":"Après le premier chat : chat"},{"id":"deuxieme","label":"Après lune : lune"},{"id":"final","label":"Après le dernier chat : chat"}]}},{"id":"ordre","prompt":"Ordonne les opérations pour traiter un mot déjà compté.","definition":{"kind":"ordering","items":[{"id":"save","label":"Enregistrer le compteur augmenté"},{"id":"read","label":"Lire le compteur actuel"},{"id":"increment","label":"Ajouter 1"}]}},{"id":"resultat","prompt":"Quelle paire de compteurs décrit les trois mots ?","definition":{"kind":"choice","mode":"single","options":[{"id":"good","label":"chat : 2; lune : 1"},{"id":"reset","label":"chat : 1; lune : 1"},{"id":"reverse","label":"chat : 1; lune : 2"}]}}],"project":{"steps":["actions","compteurs","ordre","resultat"]}}'::jsonb) on conflict(lesson_id,version) do nothing;
