insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-057','module-08','Lire le contrat d’un algorithme','exercise',57,'Un algorithme décrit une règle qui transforme une entrée en sortie. Son contrat précise aussi les cas particuliers. Un exemple aide à comprendre, mais ne remplace pas les règles qui valent pour toutes les entrées.

Avant de tracer du code, repère ce qui est fourni, ce qu’on doit produire et le comportement attendu quand une donnée manque ou que la collection est vide.','Entrée : [2, 5]
Règle : additionner les éléments
Sortie : 7','Classe chaque phrase du contrat comme entrée, règle, sortie ou cas limite.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
