insert into public.hints(id,lesson_id,position,body) values ('mvp-057-v2-h1','mvp-057',1,'Repère ce qui est fourni, la transformation demandée et le résultat.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-057-v2-h2','mvp-057',2,'Une liste vide est une entrée possible; cherche le comportement que le contrat prévoit.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-057' and version=2 and public_content<>'{"id":"mvp-057","version":2,"title":"Lire le contrat d’un algorithme","theory":[{"type":"heading","level":2,"text":"Lire le contrat d’un algorithme"},{"type":"paragraph","segments":[{"type":"text","text":"Un algorithme décrit une règle qui transforme une "},{"type":"strong","text":"entrée"},{"type":"text","text":" en "},{"type":"strong","text":"sortie"},{"type":"text","text":". Son contrat précise aussi les cas particuliers. Un exemple aide à comprendre, mais ne remplace pas les règles qui valent pour toutes les entrées."}]},{"type":"code","language":"text","code":"Entrée : [2, 5]\nRègle : additionner les éléments\nSortie : 7","output":"Pour une entrée vide, le contrat doit aussi préciser quoi retourner."},{"type":"paragraph","segments":[{"type":"text","text":"Avant de tracer du code, repère ce qui est fourni, ce qu’on doit produire et le comportement attendu quand une donnée manque ou que la collection est vide."}]}],"interactions":[{"id":"contrat","prompt":"Classe chaque phrase du contrat comme entrée, règle, sortie ou cas limite.","definition":{"kind":"classify","items":[{"id":"liste","label":"On reçoit une liste de nombres"},{"id":"addition","label":"Additionner tous les nombres"},{"id":"total","label":"Retourner leur total"},{"id":"vide","label":"La liste ne contient rien"}],"categories":[{"id":"entree","label":"Entrée"},{"id":"regle","label":"Règle"},{"id":"sortie","label":"Sortie"},{"id":"limite","label":"Cas limite"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-057 version 2'; end if; end $$;
