insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-058','module-08','Tracer un algorithme sur papier','exercise',58,'Tracer un algorithme signifie simuler ses instructions sans les exécuter. Après chaque étape, note les valeurs utiles; cela évite de sauter un tour ou d’ajouter deux fois le même nombre.

L’accumulateur garde son total entre les tours. Une petite table avec la valeur lue et le total après l’addition rend le raisonnement vérifiable.','let total = 0;
for (const n of [2, 3, 1]) total += n;','Complète le total après chaque nombre lu, puis le total final.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
