insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-059','module-08','Trouver un maximum négatif','exercise',59,'Le maximum est la plus grande valeur présente dans une liste. Pour une liste non vide, commencer par sa première valeur garantit que le résultat appartient à la liste, même si toutes ses valeurs sont négatives.

Commencer à 0 serait incorrect : 0 n’apparaît pas dans la liste et dépasse toutes ses valeurs. On compare ensuite chaque nombre au maximum connu.','Départ : maximum = -8
-3 > -8 : vrai, donc maximum = -3
-6 > -3 : faux, maximum reste -3','Trace le maximum connu après chaque valeur de la liste.',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
