insert into public.hints(id,lesson_id,position,body) values ('mvp-059-v2-h1','mvp-059',1,'Le résultat doit être choisi parmi les valeurs présentes.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-059-v2-h2','mvp-059',2,'Commence au premier nombre, même s’il est négatif, puis compare les suivants.');
