insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-060','module-08','Inverser une chaîne ASCII','exercise',60,'Pour inverser un mot ASCII, on peut le découper en caractères, inverser l’ordre du tableau, puis réunir les caractères sans séparateur. Chaque opération travaille ici sur les lettres du mot.

split("") produit [l, u, n, e]; reverse() donne [e, n, u, l]; join("") les réunit sans ajouter d’espace. L’exercice utilise des lettres ASCII simples.','const mot = "lune";
const inverse = mot.split("").reverse().join("");
console.log(inverse);','Ordonne les opérations pour inverser les caractères sans espace ajouté.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
