do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-060' and version=2 and public_content<>'{"id":"mvp-060","version":2,"title":"Inverser une chaîne ASCII","theory":[{"type":"heading","level":2,"text":"Inverser une chaîne ASCII"},{"type":"paragraph","segments":[{"type":"text","text":"Pour inverser un mot ASCII, on peut le découper en caractères, inverser l’ordre du tableau, puis réunir les caractères sans séparateur. Chaque opération travaille ici sur les lettres du mot."}]},{"type":"code","language":"javascript","code":"const mot = \"lune\";\nconst inverse = mot.split(\"\").reverse().join(\"\");\nconsole.log(inverse);","output":"enul"},{"type":"paragraph","segments":[{"type":"code","text":"split(\"\")"},{"type":"text","text":" produit "},{"type":"code","text":"[l, u, n, e]"},{"type":"text","text":"; "},{"type":"code","text":"reverse()"},{"type":"text","text":" donne "},{"type":"code","text":"[e, n, u, l]"},{"type":"text","text":"; "},{"type":"code","text":"join(\"\")"},{"type":"text","text":" les réunit sans ajouter d’espace. L’exercice utilise des lettres ASCII simples."}]}],"interactions":[{"id":"operations","prompt":"Ordonne les opérations pour inverser les caractères sans espace ajouté.","definition":{"kind":"ordering","items":[{"id":"join","label":"Réunir sans séparateur avec join(\"\")"},{"id":"reverse","label":"Inverser le tableau avec reverse()"},{"id":"split","label":"Découper le mot avec split(\"\")"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-060 version 2'; end if; end $$;
