insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-061','module-08','Détecter une répétition avec Set','exercise',61,'Un tableau peut contenir des répétitions; un Set n’en garde qu’une par valeur. Si le nombre d’éléments du Set est inférieur à la longueur du tableau, au moins une valeur était répétée.

On compare deux tailles : le nombre total d’éléments et le nombre de valeurs distinctes. Cette méthode ne demande pas de trier le tableau.','const jours = ["lun", "mar", "lun"];
const uniques = new Set(jours);','Quel cas prouve que le tableau contient une répétition ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
