do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-061' and version=2 and public_content<>'{"id":"mvp-061","version":2,"title":"Détecter une répétition avec Set","theory":[{"type":"heading","level":2,"text":"Détecter une répétition avec Set"},{"type":"paragraph","segments":[{"type":"text","text":"Un tableau peut contenir des répétitions; un "},{"type":"code","text":"Set"},{"type":"text","text":" n’en garde qu’une par valeur. Si le nombre d’éléments du Set est inférieur à la longueur du tableau, au moins une valeur était répétée."}]},{"type":"code","language":"javascript","code":"const jours = [\"lun\", \"mar\", \"lun\"];\nconst uniques = new Set(jours);","output":"jours.length = 3; uniques.size = 2"},{"type":"paragraph","segments":[{"type":"text","text":"On compare deux tailles : le nombre total d’éléments et le nombre de valeurs distinctes. Cette méthode ne demande pas de trier le tableau."}]}],"interactions":[{"id":"doublon","prompt":"Quel cas prouve que le tableau contient une répétition ?","definition":{"kind":"choice","mode":"single","options":[{"id":"repetition","label":"Le Set contient moins de valeurs que le tableau"},{"id":"egal","label":"Le Set et le tableau ont la même taille"},{"id":"tri","label":"Les éléments du Set sont triés"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-061 version 2'; end if; end $$;
