insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-062','module-08','Retourner -1 après toute la recherche','exercise',62,'Une recherche linéaire inspecte les éléments un par un. Dès qu’une valeur correspond à la cible, elle peut retourner son index; -1 ne signifie absence qu’après avoir vérifié toute la liste.

Si on retourne -1 au premier élément différent, les éléments suivants ne sont jamais examinés. Une cible située plus loin serait alors déclarée absente à tort.','function chercher(valeurs, cible) {
  for (let i = 0; i < valeurs.length; i++) {
    if (valeurs[i] === cible) return i;
  }
  return -1;
}
console.log(chercher([3, 8, 5], 8));','Sélectionne la ligne qui doit être placée après la boucle pour confirmer l’absence.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
