insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-063','module-08','Réduire une recherche binaire','exercise',63,'La recherche binaire demande une liste triée. Elle compare la cible à l’élément du milieu; selon le résultat, elle garde seulement la moitié où la cible peut encore se trouver.

Après avoir comparé 20 à 12, on écarte la moitié gauche parce que la liste est triée. Dans [16, 20, 24], le milieu vaut 20 : la recherche s’arrête. Une liste non triée ne permet pas d’écarter une moitié avec certitude.

On suit l’intervalle des index encore possibles. Au départ, les bornes sont 0 et 6; le milieu entier est l’index 3, qui contient 12.

Comme 20 est plus grand que 12, les index 0 à 3 sont écartés. Il reste 4 à 6; leur milieu est 5, qui contient 20.','const valeurs = [2, 5, 8, 12, 16, 20, 24];
const cible = 20;
// milieu : 12; puis milieu de [16, 20, 24] : 20','Après comparaison au milieu, choisis l’intervalle à garder jusqu’à trouver 20.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
