insert into public.hints(id,lesson_id,position,body) values ('mvp-063-v2-h2','mvp-063',2,'Compare au milieu; garde le côté où une valeur cible peut encore se trouver.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-063' and version=2 and public_content<>'{"id":"mvp-063","version":2,"title":"Réduire une recherche binaire","theory":[{"type":"heading","level":2,"text":"Réduire une recherche binaire"},{"type":"paragraph","segments":[{"type":"text","text":"La recherche binaire demande une liste "},{"type":"strong","text":"triée"},{"type":"text","text":". Elle compare la cible à l’élément du milieu; selon le résultat, elle garde seulement la moitié où la cible peut encore se trouver."}]},{"type":"code","language":"javascript","code":"const valeurs = [2, 5, 8, 12, 16, 20, 24];\nconst cible = 20;\n// milieu : 12; puis milieu de [16, 20, 24] : 20","output":"La cible 20 est trouvée à l’index 5."},{"type":"paragraph","segments":[{"type":"text","text":"Après avoir comparé 20 à 12, on écarte la moitié gauche parce que la liste est triée. Dans "},{"type":"code","text":"[16, 20, 24]"},{"type":"text","text":", le milieu vaut 20 : la recherche s’arrête. Une liste non triée ne permet pas d’écarter une moitié avec certitude."}]},{"type":"heading","level":3,"text":"Une étape à la fois"},{"type":"paragraph","segments":[{"type":"text","text":"On suit l’intervalle des index encore possibles. Au départ, les bornes sont 0 et 6; le milieu entier est l’index 3, qui contient 12."}]},{"type":"paragraph","segments":[{"type":"text","text":"Comme 20 est plus grand que 12, les index 0 à 3 sont écartés. Il reste 4 à 6; leur milieu est 5, qui contient 20."}]}],"interactions":[{"id":"reduction","prompt":"Après comparaison au milieu, choisis l’intervalle à garder jusqu’à trouver 20.","code":{"language":"javascript","code":"[2, 5, 8, 12, 16, 20, 24]; cible = 20"},"definition":{"kind":"trace","cells":[{"id":"milieu1","label":"Index du premier milieu"},{"id":"reste","label":"Valeurs restantes après comparaison"},{"id":"milieu2","label":"Index du milieu restant"},{"id":"trouve","label":"Index de la cible trouvée"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-063 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-063',2,'{"id":"mvp-063","version":2,"title":"Réduire une recherche binaire","theory":[{"type":"heading","level":2,"text":"Réduire une recherche binaire"},{"type":"paragraph","segments":[{"type":"text","text":"La recherche binaire demande une liste "},{"type":"strong","text":"triée"},{"type":"text","text":". Elle compare la cible à l’élément du milieu; selon le résultat, elle garde seulement la moitié où la cible peut encore se trouver."}]},{"type":"code","language":"javascript","code":"const valeurs = [2, 5, 8, 12, 16, 20, 24];\nconst cible = 20;\n// milieu : 12; puis milieu de [16, 20, 24] : 20","output":"La cible 20 est trouvée à l’index 5."},{"type":"paragraph","segments":[{"type":"text","text":"Après avoir comparé 20 à 12, on écarte la moitié gauche parce que la liste est triée. Dans "},{"type":"code","text":"[16, 20, 24]"},{"type":"text","text":", le milieu vaut 20 : la recherche s’arrête. Une liste non triée ne permet pas d’écarter une moitié avec certitude."}]},{"type":"heading","level":3,"text":"Une étape à la fois"},{"type":"paragraph","segments":[{"type":"text","text":"On suit l’intervalle des index encore possibles. Au départ, les bornes sont 0 et 6; le milieu entier est l’index 3, qui contient 12."}]},{"type":"paragraph","segments":[{"type":"text","text":"Comme 20 est plus grand que 12, les index 0 à 3 sont écartés. Il reste 4 à 6; leur milieu est 5, qui contient 20."}]}],"interactions":[{"id":"reduction","prompt":"Après comparaison au milieu, choisis l’intervalle à garder jusqu’à trouver 20.","code":{"language":"javascript","code":"[2, 5, 8, 12, 16, 20, 24]; cible = 20"},"definition":{"kind":"trace","cells":[{"id":"milieu1","label":"Index du premier milieu"},{"id":"reste","label":"Valeurs restantes après comparaison"},{"id":"milieu2","label":"Index du milieu restant"},{"id":"trouve","label":"Index de la cible trouvée"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
do $$ begin if exists (select 1 from public.interaction_definitions d join public.lesson_versions v on v.id=d.version_id where v.lesson_id='mvp-063' and v.version=2 and d.interaction_id='reduction' and (d.kind<>'trace' or d.definition<>'{"kind":"trace","cells":[{"id":"milieu1","label":"Index du premier milieu"},{"id":"reste","label":"Valeurs restantes après comparaison"},{"id":"milieu2","label":"Index du milieu restant"},{"id":"trouve","label":"Index de la cible trouvée"}]}'::jsonb)) then raise exception 'Refusing changed definition for mvp-063/reduction version 2'; end if; end $$;
insert into public.interaction_definitions(version_id,interaction_id,kind,definition) select v.id,'reduction','trace','{"kind":"trace","cells":[{"id":"milieu1","label":"Index du premier milieu"},{"id":"reste","label":"Valeurs restantes après comparaison"},{"id":"milieu2","label":"Index du milieu restant"},{"id":"trouve","label":"Index de la cible trouvée"}]}'::jsonb from public.lesson_versions v where v.lesson_id='mvp-063' and v.version=2 and not exists (select 1 from public.interaction_definitions d where d.version_id=v.id and d.interaction_id='reduction');
do $$ begin if exists (select 1 from public.interaction_keys k join public.interaction_definitions d on d.id=k.definition_id join public.lesson_versions v on v.id=d.version_id where v.lesson_id='mvp-063' and v.version=2 and d.interaction_id='reduction' and (k.answer_key<>'{"kind":"trace","accepted":{"milieu1":["3"],"reste":["16, 20, 24","16,20,24","[16, 20, 24]"],"milieu2":["5"],"trouve":["5"]}}'::jsonb or k.explanation<>'Le premier milieu est 12 à l’index 3. Comme 20 est plus grand, on garde [16, 20, 24]; le milieu restant est 20 à l’index 5.' or k.feedback<>'{"incorrect":"Compare la cible à 12 avant de choisir la moitié; la liste est triée."}'::jsonb)) then raise exception 'Refusing changed grading key for mvp-063/reduction version 2'; end if; end $$;
insert into public.interaction_keys(definition_id,answer_key,explanation,feedback) select d.id,'{"kind":"trace","accepted":{"milieu1":["3"],"reste":["16, 20, 24","16,20,24","[16, 20, 24]"],"milieu2":["5"],"trouve":["5"]}}'::jsonb,'Le premier milieu est 12 à l’index 3. Comme 20 est plus grand, on garde [16, 20, 24]; le milieu restant est 20 à l’index 5.','{"incorrect":"Compare la cible à 12 avant de choisir la moitié; la liste est triée."}'::jsonb from public.interaction_definitions d join public.lesson_versions v on v.id=d.version_id where v.lesson_id='mvp-063' and v.version=2 and d.interaction_id='reduction' and not exists (select 1 from public.interaction_keys k where k.definition_id=d.id);
