insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-064','module-08','Projet : vérifier un maximum et ses cas limites','project',64,'Pour une liste vide, le contrat du projet demande null. Pour une liste non vide, le maximum doit être une des valeurs reçues, même si elles sont toutes négatives ou répétées.

On traite d’abord la liste vide, puis on part d’une vraie valeur et on compare les suivantes. Cette règle couvre aussi bien les nombres négatifs que les doublons.','[] → null
[-5, -2, -2] → -2','Classe chaque entrée selon le résultat imposé par le contrat.
Associe chaque liste non vide à une valeur de départ qui est réellement présente.
Trace le maximum pour -5, -2, -2.
Quel résultat convient à une liste vide ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/quiz-data-structures-js','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
