insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-065','module-09','Comprendre à quoi sert Git','exercise',65,'Git enregistre l’historique des changements de fichiers et permet de comparer des versions. Une branche aide à isoler un travail. Un dépôt distant partage l’historique avec l’équipe; Git ne publie pas à lui seul un site web.

Choisis l’outil selon le besoin : retrouver une version, comparer deux changements ou travailler sur une branche distincte.','Fichier local → changements suivis par Git → dépôt distant partagé','Associe chaque besoin à la fonction Git correspondante.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
