insert into public.hints(id,lesson_id,position,body) values ('mvp-065-v2-h1','mvp-065',1,'Repère si le besoin concerne l’historique, la comparaison ou le travail isolé.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-065-v2-h2','mvp-065',2,'Git garde des commits; une branche sépare un travail, le dépôt distant le partage.');
do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-065' and version=2 and public_content<>'{"id":"mvp-065","version":2,"title":"Comprendre à quoi sert Git","theory":[{"type":"heading","level":2,"text":"Comprendre à quoi sert Git"},{"type":"paragraph","segments":[{"type":"text","text":"Git enregistre l’historique des changements de fichiers et permet de comparer des versions. Une branche aide à isoler un travail. Un dépôt distant partage l’historique avec l’équipe; Git ne publie pas à lui seul un site web."}]},{"type":"code","language":"text","code":"Fichier local → changements suivis par Git → dépôt distant partagé","output":"Git conserve et partage l’historique; il n’exécute pas l’application."},{"type":"paragraph","segments":[{"type":"text","text":"Choisis l’outil selon le besoin : retrouver une version, comparer deux changements ou travailler sur une branche distincte."}]}],"interactions":[{"id":"roles","prompt":"Associe chaque besoin à la fonction Git correspondante.","definition":{"kind":"matching","left":[{"id":"historique","label":"Retrouver un changement précédent"},{"id":"diff","label":"Voir les lignes modifiées"},{"id":"branche","label":"Travailler séparément sur une idée"}],"right":[{"id":"log","label":"Historique"},{"id":"compare","label":"Diff"},{"id":"isole","label":"Branche"}],"oneToOne":true}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-065 version 2'; end if; end $$;
