insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-066','module-09','Préparer puis enregistrer un changement','exercise',66,'Après avoir modifié un fichier, git add sélectionne les changements à inclure dans le prochain point d’historique. git commit enregistre ce point avec un message.

add ne crée pas encore le commit; il prépare son contenu. Le commit vient après et capture les changements sélectionnés.','Modifier accueil.js
git add accueil.js
git commit -m "corriger titre"','Ordonne la modification, sa préparation et son enregistrement.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
