insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-067','module-09','Lire les signes d’un diff','exercise',67,'Un diff compare une ancienne version et une nouvelle. Une ligne précédée de - a été retirée; une ligne précédée de + a été ajoutée. Les lignes sans signe donnent du contexte.

Les signes décrivent la différence; ils ne sont pas des commandes à exécuter. Pour comprendre le changement, lis la ligne retirée et celle qui la remplace.','- const titre = "Accueil";
+ const titre = "Mon espace";','Associe chaque signe à ce qu’il indique dans le diff.',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
