insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-068','module-09','Choisir une commande de branche','exercise',68,'Une branche est un nom qui pointe vers un point de l’historique et peut avancer avec de nouveaux commits. git switch -c nom crée une branche et la sélectionne. Repère l’option de création dans la commande.

Un nom court aide l’équipe à comprendre l’objectif.','git switch -c corriger-menu','Quelle commande crée une branche de travail nommée corriger-menu ?',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
