insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-069','module-09','Situer la revue avant la fusion','exercise',69,'Une pull request (PR) propose d’intégrer les changements d’une branche. Les collègues peuvent examiner le diff et les contrôles peuvent tourner; ouvrir la PR ne fusionne pas le travail automatiquement.

La revue permet de repérer un risque ou de demander un ajustement. La fusion arrive lorsque les changements sont prêts selon les règles de l’équipe.','Proposition → revue et contrôles → fusion acceptée','Ordonne les étapes d’une proposition de changement.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
