insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-070','module-09','Résoudre un conflit sans perdre un changement','exercise',70,'Un conflit apparaît quand deux changements touchent une même partie du fichier. Les marqueurs <<<<<<<, ======= et >>>>>>> délimitent les versions à comparer; la résolution conserve le résultat voulu puis retire les marqueurs.

Enlever les marqueurs ne suffit pas si l’on supprime aussi une modification. Il faut comprendre chaque côté et produire une version finale qui satisfait les deux besoins.','Version A : couleur = "bleu"
Version B : texte = "Bienvenue"
Résultat demandé : garder les deux changements','Les deux changements sont requis. Quel extrait final les conserve sans marqueur de conflit ?',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
