insert into public.hints(id,lesson_id,position,body) values ('mvp-070-v2-h1','mvp-070',1,'Relis séparément les deux changements qui doivent être conservés.');
insert into public.hints(id,lesson_id,position,body) values ('mvp-070-v2-h2','mvp-070',2,'Choisis un résultat final sans marqueurs et sans perdre l’un des deux.');
