insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-071','module-09','Écrire un commentaire de revue utile','exercise',71,'Une revue porte sur un comportement vérifiable, pas sur la valeur d’une personne. Un bon commentaire nomme un risque précis, donne un cas de reproduction et pose une question ou une demande constructive.

Un commentaire comme « ce code est mauvais » n’aide pas à comprendre quoi changer. Relie plutôt la question à une entrée et au comportement attendu.','Cas à vérifier : que renvoie la fonction quand la liste est vide ?','Quel commentaire est précis et respectueux ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
