do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-071' and version=2 and public_content<>'{"id":"mvp-071","version":2,"title":"Écrire un commentaire de revue utile","theory":[{"type":"heading","level":2,"text":"Écrire un commentaire de revue utile"},{"type":"paragraph","segments":[{"type":"text","text":"Une revue porte sur un comportement vérifiable, pas sur la valeur d’une personne. Un bon commentaire nomme un risque précis, donne un cas de reproduction et pose une question ou une demande constructive."}]},{"type":"code","language":"text","code":"Cas à vérifier : que renvoie la fonction quand la liste est vide ?","output":"La remarque vise un cas concret et vérifiable."},{"type":"paragraph","segments":[{"type":"text","text":"Un commentaire comme « ce code est mauvais » n’aide pas à comprendre quoi changer. Relie plutôt la question à une entrée et au comportement attendu."}]}],"interactions":[{"id":"commentaire","prompt":"Quel commentaire est précis et respectueux ?","definition":{"kind":"choice","mode":"single","options":[{"id":"vague","label":"C’est mal fait, recommence."},{"id":"personal","label":"Tu ne sais pas coder cette fonction."},{"id":"useful","label":"Peux-tu préciser le résultat attendu quand la liste est vide ? Le cas semble renvoyer undefined."}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-071 version 2'; end if; end $$;
