insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-072','module-09','Projet : proposer un changement à l’équipe','project',72,'Le travail commence sur une branche pour isoler l’idée. Après la modification, git add prépare les lignes choisies et un commit enregistre ce point d’historique. La branche est partagée par push, puis une PR permet la revue avant la fusion.

Observe ce workflow Git : les changements sont préparés, enregistrés et examinés avant la fusion.','branche → modification → add → commit → push → PR → revue → fusion','Ordonne le cycle complet de la branche à la fusion.
Associe add, commit et PR à leur rôle.
Que se passe-t-il après l’ouverture d’une PR, avant la fusion ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-introduction-to-git-and-github','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
