do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-072' and version=2 and public_content<>'{"id":"mvp-072","version":2,"title":"Projet : proposer un changement à l’équipe","theory":[{"type":"heading","level":2,"text":"Projet : proposer un changement à l’équipe"},{"type":"paragraph","segments":[{"type":"text","text":"Le travail commence sur une branche pour isoler l’idée. Après la modification, "},{"type":"code","text":"git add"},{"type":"text","text":" prépare les lignes choisies et un commit enregistre ce point d’historique. La branche est partagée par push, puis une PR permet la revue avant la fusion."}]},{"type":"code","language":"text","code":"branche → modification → add → commit → push → PR → revue → fusion","output":"La proposition est examinée avant son intégration."},{"type":"paragraph","segments":[{"type":"text","text":"Observe ce workflow Git : les changements sont préparés, enregistrés et examinés avant la fusion."}]}],"interactions":[{"id":"sequence","prompt":"Ordonne le cycle complet de la branche à la fusion.","definition":{"kind":"ordering","items":[{"id":"review","label":"Revue"},{"id":"branch","label":"Créer la branche"},{"id":"commit","label":"Enregistrer le commit"},{"id":"change","label":"Modifier le fichier"},{"id":"stage","label":"Préparer les lignes avec git add"},{"id":"push","label":"Partager la branche avec push"},{"id":"pr","label":"Ouvrir la PR"},{"id":"merge","label":"Fusionner"}]}},{"id":"roles","prompt":"Associe add, commit et PR à leur rôle.","definition":{"kind":"matching","left":[{"id":"add","label":"Préparer des lignes modifiées"},{"id":"commit","label":"Enregistrer un point d’historique"},{"id":"pr","label":"Proposer un changement à l’équipe"}],"right":[{"id":"stage","label":"git add"},{"id":"history","label":"git commit"},{"id":"proposal","label":"Pull request"}],"oneToOne":true}},{"id":"decision","prompt":"Que se passe-t-il après l’ouverture d’une PR, avant la fusion ?","definition":{"kind":"choice","mode":"single","options":[{"id":"auto","label":"La PR fusionne toujours tout de suite"},{"id":"review","label":"L’équipe examine le diff et les contrôles"},{"id":"execute","label":"Le code s’exécute sur l’ordinateur du lecteur"}]}}],"project":{"steps":["sequence","roles","decision"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-072 version 2'; end if; end $$;
