id":"auto","label":"La PR fusionne toujours tout de suite"},{"id":"review","label":"L’équipe examine le diff et les contrôles"},{"id":"execute","label":"Le code s’exécute sur l’ordinateur du lecteur"}]}}],"project":{"steps":["sequence","roles","decision"]}}'::jsonb) on conflict(lesson_id,version) do nothing;
