insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-073','module-10','Suivre une requête jusqu’à sa réponse','exercise',73,'Une API permet à un programme client de demander une opération à un serveur. Le serveur reçoit la requête, vérifie les règles d’accès, traite la demande puis renvoie une réponse que le client peut lire.

Le client peut être une page web ou une application. Il ne décide pas seul qu’un utilisateur a le droit de consulter ou modifier une donnée : le serveur doit vérifier cette autorisation.

Masquer un bouton dans la page améliore l’interface, mais ne protège pas une route. Un utilisateur peut fabriquer une requête; chaque opération sensible doit donc vérifier l’identité et les droits côté serveur.','Client → requête → serveur
Client ← réponse ← serveur','Associe chaque rôle à son action dans l’échange.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
