do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-073' and version=2 and public_content<>'{"id":"mvp-073","version":2,"title":"Suivre une requête jusqu’à sa réponse","theory":[{"type":"heading","level":2,"text":"Suivre une requête jusqu’à sa réponse"},{"type":"paragraph","segments":[{"type":"text","text":"Une API permet à un programme client de demander une opération à un serveur. Le serveur reçoit la requête, vérifie les règles d’accès, traite la demande puis renvoie une réponse que le client peut lire."}]},{"type":"code","language":"text","code":"Client → requête → serveur\nClient ← réponse ← serveur","output":"Le serveur traite la demande et renvoie une réponse."},{"type":"paragraph","segments":[{"type":"text","text":"Le client peut être une page web ou une application. Il ne décide pas seul qu’un utilisateur a le droit de consulter ou modifier une donnée : le serveur doit vérifier cette autorisation."}]},{"type":"heading","level":3,"text":"La réponse ne prouve pas un droit"},{"type":"paragraph","segments":[{"type":"text","text":"Masquer un bouton dans la page améliore l’interface, mais ne protège pas une route. Un utilisateur peut fabriquer une requête; chaque opération sensible doit donc vérifier l’identité et les droits côté serveur."}]}],"interactions":[{"id":"acteurs","prompt":"Associe chaque rôle à son action dans l’échange.","definition":{"kind":"matching","left":[{"id":"client","label":"Client"},{"id":"serveur","label":"Serveur"},{"id":"reponse","label":"Réponse"}],"right":[{"id":"demande","label":"Envoie une demande"},{"id":"traite","label":"Vérifie et traite la demande"},{"id":"retour","label":"Revient du serveur vers le client"}],"oneToOne":true}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-073 version 2'; end if; end $$;
