insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-074','module-10','Lire les parties d’une requête HTTP','exercise',74,'Une requête HTTP contient une méthode, un chemin et parfois des en-têtes et un corps. La méthode indique l’intention générale; le chemin nomme la ressource; les en-têtes donnent des informations sur l’échange et le corps transporte des données envoyées.

Une ligne HTTP réelle peut contenir davantage de détails, mais ces quatre éléments suffisent pour cette lecture. Le chemin n’est pas une méthode : c’est l’adresse de la ressource visée.

Content-Type: application/json annonce que le corps envoyé est au format JSON. Le corps contient ici un identifiant de leçon; il ne donne pas à lui seul le droit de modifier cette leçon.','POST /api/attempts
Content-Type: application/json
{"lessonId":"mvp-074"}','Classe chaque fragment dans la partie correspondante de la requête.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
