insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-075','module-10','Choisir GET ou POST','exercise',75,'GET sert généralement à lire une ressource. POST sert généralement à envoyer une nouvelle donnée ou demander une action qui crée un résultat. Ce sont des usages courants, pas une preuve d’autorisation : le serveur doit toujours vérifier les droits.

Une tentative d’exercice ajoute une donnée à l’historique. La soumettre avec GET serait inadapté, car GET sert à lire et peut être répété ou conservé par des mécanismes de cache.

Utiliser POST ne rend pas une requête automatiquement sûre. Le serveur doit vérifier la session, l’accès à la leçon et les règles de validation avant d’enregistrer la tentative.','Lire le profil → GET
Envoyer une tentative → POST','Quelle méthode convient pour envoyer la réponse d’un exercice au serveur ?',10,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
