insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-076','module-10','Lire les familles de statuts HTTP','exercise',76,'Le premier chiffre d’un statut HTTP donne une famille. Les statuts 2xx signalent un succès HTTP, 3xx une redirection, 4xx un problème lié à la requête ou à l’accès, et 5xx une erreur du serveur.

Un succès HTTP signifie que l’échange a été traité selon le protocole; il ne garantit pas que les données répondent à la règle métier attendue. Il faut aussi vérifier la forme et le contenu du corps.

Une réponse 200 peut contenir une liste vide ou un message indiquant que l’opération n’a pas produit le résultat attendu. Lis le statut et la réponse, puis applique les règles de l’application.','200 → succès HTTP
302 → redirection
403 → accès refusé
500 → erreur serveur','Classe chaque code par famille HTTP.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
