insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-077','module-10','Analyser du JSON avant de lire ses champs','exercise',77,'JSON est un format texte qui représente des valeurs comme des nombres, des chaînes, des booléens, des tableaux et des objets. Après réception, JSON.parse(texte) transforme un texte JSON valide en valeur JavaScript que le programme peut lire.

Avant JSON.parse, texte est une chaîne : on ne peut pas y lire directement score comme une propriété d’objet. Après l’analyse, data est un objet et data.score accède à sa valeur.

Si le serveur annonce du JSON mais renvoie un texte mal formé, l’analyse échoue. Ici, on suppose que la réponse est un JSON valide afin de se concentrer sur la transformation texte → valeur JavaScript.','const texte = ''{"score": 8}'';
const data = JSON.parse(texte);
console.log(data.score);','Après JSON.parse(texte), quelle expression lit le score de l’objet obtenu ?',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
