SON.parse(texte);"},"definition":{"kind":"choice","mode":"single","options":[{"id":"parsed","label":"data.score"},{"id":"raw","label":"texte.score"},{"id":"wrong-name","label":"data.points"}]}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-077 version 2'; end if; end $$;
