insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-078','module-10','Lire une propriété après réception','exercise',78,'Une réponse peut d’abord arriver comme texte JSON. Il faut analyser ce texte avec JSON.parse, puis accéder à la propriété de l’objet obtenu. Lire json.name directement sur la chaîne ne lit pas le champ du JSON.

Le nom de la variable json n’impose pas son type; c’est le résultat de JSON.parse qui compte. Dans cet exemple, json contient un objet JavaScript avec le champ name.

On reçoit le texte, on le transforme en valeur JavaScript, puis on lit un champ de cette valeur. Chaque étape utilise le résultat de la précédente.','const texte = ''{"name":"Mina"}'';
const json = JSON.parse(texte);
console.log(json.name);','Ordonne la réception du texte, son analyse JSON puis la lecture de name.',20,8,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
