insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-078',2,'{"id":"mvp-078","version":2,"title":"Lire une propriété après réception","theory":[{"type":"heading","level":2,"text":"Lire une propriété après réception"},{"type":"paragraph","segments":[{"type":"text","text":"Une réponse peut d’abord arriver comme texte JSON. Il faut analyser ce texte avec "},{"type":"code","text":"JSON.parse"},{"type":"text","text":", puis accéder à la propriété de l’objet obtenu. Lire "},{"type":"code","text":"json.name"},{"type":"text","text":" directement sur la chaîne ne lit pas le champ du JSON."}]},{"type":"code","language":"javascript","code":"const texte = ''{\"name\":\"Mina\"}'';\nconst json = JSON.parse(texte);\nconsole.log(json.name);","output":"Mina"},{"type":"paragraph","segments":[{"type":"text","text":"Le nom de la variable "},{"type":"code","text":"json"},{"type":"text","text":" n’impose pas son type; c’est le résultat de "},{"type":"code","text":"JSON.parse"},{"type":"text","text":" qui compte. Dans cet exemple, "},{"type":"code","text":"json"},{"type":"text","text":" contient un objet JavaScript avec le champ "},{"type":"code","text":"name"},{"type":"text","text":"."}]},{"type":"heading","level":3,"text":"Trois étapes dans l’ordre"},{"type":"paragraph","segments":[{"type":"text","text":"On reçoit le texte, on le transforme en valeur JavaScript, puis on lit un champ de cette valeur. Chaque étape utilise le résultat de la précédente."}]}],"interactions":[{"id":"etapes","prompt":"Ordonne la réception du texte, son analyse JSON puis la lecture de name.","definition":{"kind":"ordering","items":[{"id":"access","label":"Lire json.name"},{"id":"receive","label":"Recevoir le texte JSON"},{"id":"parse","label":"Analyser avec JSON.parse"}]}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
