insert into public.interaction_definitions(version_id,interaction_id,kind,definition) select v.id,'etapes','ordering','{"kind":"ordering","items":[{"id":"access","label":"Lire json.name"},{"id":"receive","label":"Recevoir le texte JSON"},{"id":"parse","label":"Analyser avec JSON.parse"}]}'::jsonb from public.lesson_versions v where v.lesson_id='mvp-078' and v.version=2 and not exists (select 1 from public.interaction_definitions d where d.version_id=v.id and d.interaction_id='etapes');
