insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-079','module-10','Comprendre une origine CORS','exercise',79,'Une origine est formée du protocole, de l’hôte et du port. http://localhost:3000 et http://localhost:4000 ont des origines différentes parce que le port change. https://localhost:3000 en est aussi une autre, car le protocole change.

Pour une requête entre origines, le serveur peut envoyer un en-tête qui annonce les origines autorisées. Le navigateur applique alors la politique CORS et décide si le code de la page peut lire la réponse.

Pour HTTP, le port par défaut est 80; pour HTTPS, il est 443. Écrire http://site.exemple revient à utiliser le port 80, et https://site.exemple le port 443. Le protocole et le port restent deux parties de l’origine.

CORS encadre la lecture d’une réponse par du code exécuté dans un navigateur. Il ne remplace ni l’authentification ni l’autorisation côté serveur : l’API doit encore vérifier qui demande l’opération et quels droits cette personne possède.','http://localhost:3000 → http://localhost:4000
http://localhost:3000 → https://localhost:3000','Associe chaque élément au rôle correspondant dans CORS.',10,5,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
