do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-079' and version=2 and public_content<>'{"id":"mvp-079","version":2,"title":"Comprendre une origine CORS","theory":[{"type":"heading","level":2,"text":"Comprendre une origine CORS"},{"type":"paragraph","segments":[{"type":"text","text":"Une origine est formée du protocole, de l’hôte et du port. "},{"type":"code","text":"http://localhost:3000"},{"type":"text","text":" et "},{"type":"code","text":"http://localhost:4000"},{"type":"text","text":" ont des origines différentes parce que le port change. "},{"type":"code","text":"https://localhost:3000"},{"type":"text","text":" en est aussi une autre, car le protocole change."}]},{"type":"code","language":"text","code":"http://localhost:3000 → http://localhost:4000\nhttp://localhost:3000 → https://localhost:3000","output":"Un port ou protocole différent signifie une origine différente."},{"type":"paragraph","segments":[{"type":"text","text":"Pour une requête entre origines, le serveur peut envoyer un en-tête qui annonce les origines autorisées. Le navigateur applique alors la politique CORS et décide si le code de la page peut lire la réponse."}]},{"type":"heading","level":3,"text":"Les ports implicites"},{"type":"paragraph","segments":[{"type":"text","text":"Pour HTTP, le port par défaut est 80; pour HTTPS, il est 443. Écrire "},{"type":"code","text":"http://site.exemple"},{"type":"text","text":" revient à utiliser le port 80, et "},{"type":"code","text":"https://site.exemple"},{"type":"text","text":" le port 443. Le protocole et le port restent deux parties de l’origine."}]},{"type":"heading","level":3,"text":"CORS n’est pas une autorisation utilisateur"},{"type":"paragraph","segments":[{"type":"text","text":"CORS encadre la lecture d’une réponse par du code exécuté dans un navigateur. Il ne remplace ni l’authentification ni l’autorisation côté serveur : l’API doit encore vérifier qui demande l’opération et quels droits cette personne possède."}]}],"interactions":[{"id":"cors","prompt":"Associe chaque élément au rôle correspondant dans CORS.","definition":{"kind":"matching","left":[{"id":"origin","label":"Origine"},{"id":"server","label":"Serveur de l’API"},{"id":"browser","label":"Navigateur"},{"id":"auth","label":"Autorisation"}],"right":[{"id":"tuple","label":"Protocole, hôte et port"},{"id":"announce","label":"Annonce les origines permises"},{"id":"enforce","label":"Applique la règle de lecture"},{"id":"rights","label":"Vérifie les droits de la personne"}],"oneToOne":true}}]}'::jsonb) then raise exception 'Refusing changed public content for mvp-079 version 2'; end if; end $$;
