ors","prompt":"Associe chaque élément au rôle correspondant dans CORS.","definition":{"kind":"matching","left":[{"id":"origin","label":"Origine"},{"id":"server","label":"Serveur de l’API"},{"id":"browser","label":"Navigateur"},{"id":"auth","label":"Autorisation"}],"right":[{"id":"tuple","label":"Protocole, hôte et port"},{"id":"announce","label":"Annonce les origines permises"},{"id":"enforce","label":"Applique la règle de lecture"},{"id":"rights","label":"Vérifie les droits de la personne"}],"oneToOne":true}}]}'::jsonb) on conflict(lesson_id,version) do nothing;
