insert into public.lessons(id,module_id,title,type,position,body,example,instructions,xp,duration_minutes,license,attribution,source_url,modifications) values ('mvp-080','module-10','Projet : vérifier une réponse d’API','project',80,'Une page reçoit une réponse simulée avec un statut et un corps. Avant de lire la longueur des éléments, elle vérifie le succès HTTP, puis que body.items est bien un tableau. Si l’un de ces contrôles échoue, le nombre affiché est 0.

Cette activité lit une réponse fournie dans l’exercice : elle ne fait aucune requête réseau. Un statut réussi et une structure valide sont deux vérifications distinctes; il faut faire les deux avant de lire length.

Array.isArray(valeur) renvoie true si la valeur est un tableau et false sinon. Cela permet de vérifier la structure du corps avant de lire length.

Par exemple, Array.isArray([1, 2]) vaut true, tandis que Array.isArray(2) vaut false. On ne lit donc body.items.length qu’après avoir confirmé que body.items est un tableau.','status = 200
body = { items: ["carte", "pion"] }
resultat = 2','Classe les statuts selon qu’ils indiquent un succès HTTP.
Associe chaque vérification à ce qu’elle contrôle.
Ordonne les contrôles avant le calcul du résultat.
Le statut vaut 200 et items contient deux éléments. Quel nombre est affiché ?',10,15,'LicenseRef-LiteCode-Original','Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.','https://github.com/freeCodeCamp/freeCodeCamp/tree/main/curriculum/challenges/english/blocks/lecture-understanding-the-http-request-response-model','["Explications, exercices, exemples et tests originaux en français ; référence thématique seulement."]'::jsonb) on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,type=excluded.type,position=excluded.position,body=excluded.body,example=excluded.example,instructions=excluded.instructions,xp=excluded.xp,duration_minutes=excluded.duration_minutes,license=excluded.license,attribution=excluded.attribution,source_url=excluded.source_url,modifications=excluded.modifications;
