do $$ begin if exists (select 1 from public.lesson_versions where lesson_id='mvp-080' and version=2 and public_content<>'{"id":"mvp-080","version":2,"title":"Projet : vérifier une réponse d’API","theory":[{"type":"heading","level":2,"text":"Projet : vérifier une réponse d’API"},{"type":"paragraph","segments":[{"type":"text","text":"Une page reçoit une réponse simulée avec un statut et un corps. Avant de lire la longueur des éléments, elle vérifie le succès HTTP, puis que "},{"type":"code","text":"body.items"},{"type":"text","text":" est bien un tableau. Si l’un de ces contrôles échoue, le nombre affiché est 0."}]},{"type":"code","language":"text","code":"status = 200\nbody = { items: [\"carte\", \"pion\"] }\nresultat = 2","output":"Le statut est réussi et items est un tableau de longueur 2."},{"type":"paragraph","segments":[{"type":"text","text":"Cette activité lit une réponse fournie dans l’exercice : elle ne fait aucune requête réseau. Un statut réussi et une structure valide sont deux vérifications distinctes; il faut faire les deux avant de lire "},{"type":"code","text":"length"},{"type":"text","text":"."}]},{"type":"heading","level":3,"text":"Vérifier qu’une valeur est un tableau"},{"type":"paragraph","segments":[{"type":"code","text":"Array.isArray(valeur)"},{"type":"text","text":" renvoie "},{"type":"code","text":"true"},{"type":"text","text":" si la valeur est un tableau et "},{"type":"code","text":"false"},{"type":"text","text":" sinon. Cela permet de vérifier la structure du corps avant de lire "},{"type":"code","text":"length"},{"type":"text","text":"."}]},{"type":"paragraph","segments":[{"type":"text","text":"Par exemple, "},{"type":"code","text":"Array.isArray([1, 2])"},{"type":"text","text":" vaut "},{"type":"code","text":"true"},{"type":"text","text":", tandis que "},{"type":"code","text":"Array.isArray(2)"},{"type":"text","text":" vaut "},{"type":"code","text":"false"},{"type":"text","text":". On ne lit donc "},{"type":"code","text":"body.items.length"},{"type":"text","text":" qu’après avoir confirmé que "},{"type":"code","text":"body.items"},{"type":"text","text":" est un tableau."}]}],"interactions":[{"id":"statut","prompt":"Classe les statuts selon qu’ils indiquent un succès HTTP.","definition":{"kind":"classify","items":[{"id":"ok","label":"200"},{"id":"created","label":"201"},{"id":"missing","label":"404"},{"id":"server","label":"500"}],"categories":[{"id":"success","label":"Succès HTTP : 2xx"},{"id":"not-success","label":"Autre famille"}]}},{"id":"structure","prompt":"Associe chaque vérification à ce qu’elle contrôle.","definition":{"kind":"matching","left":[{"id":"status-check","label":"status >= 200 && status < 300"},{"id":"array-check","label":"Array.isArray(body.items)"},{"id":"length","label":"body.items.length"}],"right":[{"id":"http","label":"Le statut est 2xx"},{"id":"type","label":"items est un tableau"},{"id":"count","label":"Nombre d’éléments"}],"oneToOne":true}},{"id":"ordre","prompt":"Ordonne les contrôles avant le calcul du résultat.","definition":{"kind":"ordering","items":[{"id":"count","label":"Lire items.length"},{"id":"http","label":"Vérifier le statut 2xx"},{"id":"array","label":"Vérifier que items est un tableau"}]}},{"id":"resultat","prompt":"Le statut vaut 200 et items contient deux éléments. Quel nombre est affiché ?","definition":{"kind":"choice","mode":"single","options":[{"id":"zero","label":"0, car une réponse HTTP ne contient jamais de résultat"},{"id":"two","label":"2, la longueur du tableau items"},{"id":"one","label":"1, car il faut compter la réponse elle-même"}]}}],"project":{"steps":["statut","structure","ordre","resultat"]}}'::jsonb) then raise exception 'Refusing changed public content for mvp-080 version 2'; end if; end $$;
insert into public.lesson_versions(lesson_id,version,public_content) values ('mvp-080',2,'{"id":"mvp-080","version":2,"title":"Projet : vérifier une réponse d’API","theory":[{"type":"heading","level":2,"text":"Projet : vérifier une réponse d’API"},{"type":"paragraph","segments":[{"type":"text","text":"Une page reçoit une réponse simulée avec un statut et un corps. Avant de lire la longueur des éléments, elle vérifie le succès HTTP, puis que "},{"type":"code","text":"body.items"},{"type":"text","text":" est bien un tableau. Si l’un de ces contrôles échoue, le nombre affiché est 0."}]},{"type":"code","language":"text","code":"status = 200\nbody = { items: [\"carte\", \"pion\"] }\nresultat = 2","output":"Le statut est réussi et items est un tableau de longueur 2."},{"type":"paragraph","segments":[{"type":"text","text":"Cette activité lit une réponse fournie dans l’exercice : elle ne fait aucune requête réseau. Un statut réussi et une structure valide sont deux vérifications distinctes; il faut faire les deux avant de lire "},{"type":"code","text":"length"},{"type":"text","text":"."}]},{"type":"heading","level":3,"text":"Vérifier qu’une valeur est un tableau"},{"type":"paragraph","segments":[{"type":"code","text":"Array.isArray(valeur)"},{"type":"text","text":" renvoie "},{"type":"code","text":"true"},{"type":"text","text":" si la valeur est un tableau et "},{"type":"code","text":"false"},{"type":"text","text":" sinon. Cela permet de vérifier la structure du corps avant de lire "},{"type":"code","text":"length"},{"type":"text","text":"."}]},{"type":"paragraph","segments":[{"type":"text","text":"Par exemple, "},{"type":"code","text":"Array.isArray([1, 2])"},{"type":"text","text":" vaut "},{"type":"code","text":"true"},{"type":"text","text":", tandis que "},{"type":"code","text":"Array.isArray(2)"},{"type":"text","text":" vaut "},{"type":"code","text":"false"},{"type":"text","text":". On ne lit donc "},{"type":"code","text":"body.items.length"},{"type":"text","text":" qu’après avoir confirmé que "},{"type":"code","text":"body.items"},{"type":"text","text":" est un tableau."}]}],"interactions":[{"id":"statut","prompt":"Classe les statuts selon qu’ils indiquent un succès HTTP.","definition":{"kind":"classify","items":[{"id":"ok","label":"200"},{"id":"created","label":"201"},{"id":"missing","label":"404"},{"id":"server","label":"500"}],"categories":[{"id":"success","label":"Succès HTTP : 2xx"},{"id":"not-success","label":"Autre famille"}]}},{"id":"structure","prompt":"Associe chaque vérification à ce qu’elle contrôle.","definition":{"kind":"matching","left":[{"id":"status-check","label":"status >= 200 && status < 300"},{"id":"array-check","label":"Array.isArray(body.items)"},{"id":"length","label":"body.items.length"}],"right":[{"id":"http","label":"Le statut est 2xx"},{"id":"type","label":"items est un tableau"},{"id":"count","label":"Nombre d’éléments"}],"oneToOne":true}},{"id":"ordre","prompt":"Ordonne les contrôles avant le calcul du résultat.","definition":{"kind":"ordering","items":[{"id":"count","label":"Lire items.length"},{"id":"http","label":"Vérifier le statut 2xx"},{"id":"array","label":"Vérifier que items est un tableau"}]}},{"id":"resultat","prompt":"Le statut vaut 200 et items contient deux éléments. Quel nombre est affiché ?","definition":{"kind":"choice","mode":"single","options":[{"id":"zero","label":"0, car une réponse HTTP ne contient jamais de résultat"},{"id":"two","label":"2, la longueur du tableau items"},{"id":"one","label":"1, car il faut compter la réponse elle-même"}]}}],"project":{"steps":["statut","structure","ordre","resultat"]}}'::jsonb) on conflict(lesson_id,version) do nothing;
